async function refreshHub(rerender=false){try{const snap=await SafeApi.get('/api/safe/snapshot?portal=ecosystem');const key=JSON.stringify(snap||null);if(key!==hubKey){hubKey=key;hubStale=true}applySnap(snap);if(rerender==='poll'){if(hubStale&&!userIsEditing()){hubStale=false;render()}}else{hubStale=false;if(rerender)render()}return true}catch(e){console.warn('IndorDB snapshot unavailable',e);return false}}
