const STATUS_ES={'new':'Nuevo','active':'Activo','inspection':'Inspección','under contract':'Bajo contrato','closed':'Cerrado','completed':'Completado','complete':'Completado','done':'Completado','scheduled':'Programado','review':'En revisión','in review':'En revisión','cancelled':'Cancelado','canceled':'Cancelado','on hold':'En pausa'};
