function applyLanguage(){
  document.documentElement.lang=state.lang;
  document.querySelectorAll('[data-i18n]').forEach(node=>{const pair=I18N[node.dataset.i18n];if(pair)node.textContent=pair[state.lang==='en'?0:1]});
  document.querySelectorAll('[data-placeholder-en]').forEach(node=>node.placeholder=state.lang==='en'?node.dataset.placeholderEn:node.dataset.placeholderEs);
  document.querySelectorAll('[data-aria-es]').forEach(node=>{if(!node.dataset.ariaEn)node.dataset.ariaEn=node.getAttribute('aria-label')||'';node.setAttribute('aria-label',state.lang==='en'?node.dataset.ariaEn:node.dataset.ariaEs)});
  if(el('giftCard'))updateGiftPreview();
  el('languageBtn').textContent=state.lang==='en'?'ES':'EN';
  const shortcut=el('searchShortcut');if(shortcut){shortcut.textContent=`${/Mac|iPhone|iPad/.test(navigator.platform||navigator.userAgent)?'⌘':'Ctrl'} K`;shortcut.title=t('Shortcut to search','Atajo para buscar')}
  if(state.loggedIn)paintRealtor();
}
function navigate(route){
  if(!state.loggedIn&&!publicRoutes.has(route)){
    state.pendingRoute=route;
    openModal('loginModal');
    return;
  }
  if(route!==state.route)state.previousRoute=state.route;
  state.route=route;location.hash=route;
  document.querySelectorAll('[data-route]').forEach(b=>b.classList.toggle('active',b.dataset.route===route&&b.closest('.nav')));
  render();
  closeNavMenus();closeProfileMenu();
  el('main').focus({preventScroll:true});window.scrollTo({top:0,behavior:'smooth'});
}
function goBack(){
  if(state.route==='home'||state.route==='welcome')return;
  const fallback=state.loggedIn?'home':'welcome';
  const previous=state.previousRoute&&state.previousRoute!==state.route?state.previousRoute:fallback;
  navigate(state.loggedIn&&previous==='welcome'?'home':previous);
}
function toast(message){const box=el('toast');box.textContent=message;box.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>box.classList.remove('show'),2600)}
function estimateKey(){return state.account?.email?`safe-estimate:${state.account.email.toLowerCase()}`:''}
function loadEstimate(){if(!estimateKey()){state.estimate=[];state.transportAmount=0;return}try{state.estimate=JSON.parse(localStorage.getItem(estimateKey())||'[]')}catch{state.estimate=[]}state.transportAmount=Number(localStorage.getItem(estimateKey()+':transport'))||0}
function persistEstimate(){if(estimateKey()){localStorage.setItem(estimateKey(),JSON.stringify(state.estimate));localStorage.setItem(estimateKey()+':transport',String(state.transportAmount||0))};updateCounts();renderDrawer()}
function clearSessionWork(){const key=estimateKey();state.plan=null;state.plans=[];state.clientProfiles=[];state.planQuery='';state.estimate=[];state.transportAmount=0;state.reportReady=false;state.reportName='';state.reports=[];state.reportReading=false;localStorage.removeItem('safe-estimate');sessionStorage.removeItem('safe-realtor-reports');if(key){localStorage.removeItem(key);localStorage.removeItem(key+':transport')};updateCounts();renderDrawer()}
function visitKey(){return state.account?.email?`safe-realtor-visits:${state.account.email.toLowerCase()}`:'safe-realtor-visits'}
function loadVisits(){try{return JSON.parse(localStorage.getItem(visitKey())||'[]')}catch{return[]}}
function saveVisits(list){localStorage.setItem(visitKey(),JSON.stringify(list));updateCounts()}
function visitBucket(visit){if(visit.done)return 'done';const today=new Date();today.setHours(0,0,0,0);const when=new Date(`${visit.date}T00:00:00`);if(Number.isNaN(when.getTime())||when.getTime()<=today.getTime())return 'today';return 'next'}
function visitWhen(visit){const date=visit.date?new Date(`${visit.date}T00:00:00`).toLocaleDateString(state.lang==='en'?'en-US':'es-ES',{month:'short',day:'numeric'}):'';return [date,visit.time].filter(Boolean).join(' · ')}
function updateCounts(){el('estimateCount').textContent=state.estimate.length;el('sideEstimateCount').textContent=state.estimate.length;const open=loadVisits().filter(v=>!v.done).length;document.querySelectorAll('.nav [data-route="followups"] em').forEach(node=>{node.textContent=open;node.hidden=!open})}
function openDrawer(){if(!state.loggedIn){state.pendingRoute='estimates';openModal('loginModal');return}renderDrawer();el('estimateDrawer').classList.add('open');el('estimateDrawer').setAttribute('aria-hidden','false');el('overlay').classList.add('open')}
function closeDrawer(){el('estimateDrawer').classList.remove('open');el('estimateDrawer').setAttribute('aria-hidden','true');el('overlay').classList.remove('open')}
function openModal(id){el(id).classList.add('open');if(id==='loginModal')showRealtorGate('choices')}
function closeModals(){document.querySelectorAll('.modal.open').forEach(m=>m.classList.remove('open'))}
function closeProfileMenu(){el('profileMenu')?.classList.remove('open');el('profileMenu')?.setAttribute('aria-hidden','true');el('profileBtn')?.setAttribute('aria-expanded','false')}
function closeNavMenus(){
  el('sidebar')?.classList.remove('open');
  el('publicMenu')?.classList.remove('open');
  el('publicMenu')?.setAttribute('aria-hidden','true');
  el('mobileMenu')?.setAttribute('aria-expanded','false');
  el('overlay')?.classList.remove('open');
}
