function saveRealtorAccounts(list){localStorage.setItem('safe-realtor-accounts',JSON.stringify(list))}
function readRealtorSession(){try{return JSON.parse(sessionStorage.getItem('safe-realtor-session')||'null')}catch{return null}}
function rememberRealtor(account){state.account=account;sessionStorage.setItem('safe-realtor-session',JSON.stringify(account));markActive(true);paintRealtor()}
const IDLE_LIMIT=30*60*1000;
function markActive(force){const now=Date.now();if(!force&&now-(markActive.at||0)<30000)return;markActive.at=now;sessionStorage.setItem('safe-realtor-active',String(now))}
function sessionIdle(){return Date.now()-(Number(sessionStorage.getItem('safe-realtor-active'))||0)>IDLE_LIMIT}
function endIdleSession(){sessionStorage.removeItem('safe-realtor-session');sessionStorage.removeItem('safe-realtor-active');sessionStorage.setItem('safe-realtor-expired',JSON.stringify({email:state.account?.email||'',route:state.route}))}
function expireIfIdle(){if(!state.loggedIn||!sessionIdle())return;endIdleSession();location.reload()}
async function sendCompanyEmail(to,subject,body){
  try{
    const r=await fetch('/api/safe/email',{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify({to,subject,body,replyTo:state.account?.email||'',replyName:state.account?.name||''})});
    return r.ok?'sent':r.status===503?'off':'failed';
  }catch{return 'failed'}
}
function openMailDraft(to,subject,body){if(body.length<1600)window.location.href=`mailto:${encodeURIComponent(to)}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`}
const PHONE_ATTRS='type="tel" inputmode="numeric" maxlength="10" pattern="[0-9]{10}" autocomplete="tel" data-phone';
const PHONE_ERROR=()=>t('The phone must have exactly 10 digits, numbers only.','El teléfono debe tener exactamente 10 dígitos, solo números.');
const pad2=n=>String(n).padStart(2,'0');
function todayLocal(){const d=new Date();return `${d.getFullYear()}-${pad2(d.getMonth()+1)}-${pad2(d.getDate())}`}
function nowTimeLocal(){const d=new Date();return `${pad2(d.getHours())}:${pad2(d.getMinutes())}`}
function validPhone(value){return !value||/^\d{10}$/.test(value)}
document.addEventListener('input',e=>{if(e.target.matches?.('[data-phone]')){const clean=e.target.value.replace(/\D/g,'').slice(0,10);if(clean!==e.target.value)e.target.value=clean}});
function validEmail(value){return /^[^\s@]+@[^\s@]+\.[A-Za-z]{2,}$/.test(String(value||'').trim())}
function validityText(f){
  const v=f.validity;
  if(v.valueMissing)return f.type==='checkbox'?t('Check this box to continue.','Marca esta casilla para continuar.'):f.tagName==='SELECT'?t('Choose an option from the list.','Elige una opción de la lista.'):t('Fill out this field.','Completa este campo.');
  if(f.type==='email'&&(v.typeMismatch||v.patternMismatch))return I18N.badEmail[state.lang==='en'?0:1];
  if(v.patternMismatch&&f.matches('[data-phone]'))return PHONE_ERROR();
  if(v.tooShort)return t(`Use at least ${f.minLength} characters.`,`Usa al menos ${f.minLength} caracteres.`);
  if(v.valid)return '';
  return t('Check the value of this field.','Revisa el valor de este campo.');
}
document.addEventListener('invalid',e=>{const f=e.target;if(f.validity.customError&&!f.dataset.portalMsg)return;f.setCustomValidity('');const msg=validityText(f);if(msg){f.setCustomValidity(msg);f.dataset.portalMsg='1'}},true);
['input','change'].forEach(type=>document.addEventListener(type,e=>{const f=e.target;if(f?.dataset?.portalMsg){f.setCustomValidity('');delete f.dataset.portalMsg}},true));
