function firmFieldHtml(id,value){
  const other=!!value&&value!==NO_FIRM&&!CHARLOTTE_FIRMS.includes(value);
  return `<select id="${id}" required><option value="">${t('Choose your firm','Elige tu firma')}</option>${CHARLOTTE_FIRMS.map(f=>`<option value="${esc(f)}"${f===value?' selected':''}>${esc(f)}</option>`).join('')}<option value="__other"${other?' selected':''}>${t('Other firm in Charlotte','Otra firma en Charlotte')}</option><option value="${NO_FIRM}"${value===NO_FIRM?' selected':''}>${t('None','Ninguna')}</option></select><input id="${id}Other" placeholder="${t('Firm name','Nombre de la firma')}" value="${other?esc(value):''}"${other?'':' hidden'}>`;
}
function wireFirmField(id){const s=el(id),o=el(id+'Other');if(!s||!o)return;s.onchange=()=>{o.hidden=s.value!=='__other';o.required=!o.hidden;if(!o.hidden)o.focus()};o.required=!o.hidden}
function readFirm(id){const v=el(id)?.value||'';return v==='__other'?(el(id+'Other')?.value.trim()||''):v}
function paintCreateFirm(){const box=el('createFirmField');if(!box)return;box.innerHTML=firmFieldHtml('createFirm',readFirm('createFirm'));wireFirmField('createFirm')}
function paintRealtor(){
  const account=state.account;
  if(!account)return;
  const mark=initials(account.name||'R')||'R';
  const firm=!account.firm?'':account.firm===NO_FIRM?t('No realty firm','Sin firma inmobiliaria'):`${t('Firm','Firma')}: ${account.firm}`;
  [['profileInitial',mark],['menuInitial',mark],['partnerInitial',mark]].forEach(([id,value])=>{const node=el(id);if(!node)return;if(state.logo){node.innerHTML=`<img src="${esc(state.logo)}" alt="" class="avatar-logo">`}else node.textContent=value});
  if(el('menuName'))el('menuName').textContent=account.name||'';
  if(el('menuFirm'))el('menuFirm').textContent=firm;
  if(el('partnerName'))el('partnerName').textContent=account.name||'';
  if(el('partnerFirm'))el('partnerFirm').textContent=firm;
}
function showRealtorGate(mode){
  state.loginMode=mode;
  const choices=el('realtorChoices'),create=el('realtorCreate'),sign=el('realtorSignIn'),form=el('loginForm'),title=el('loginTitle');
  if(!choices||!create||!sign)return;
  choices.hidden=mode!=='choices';
  form.hidden=mode==='choices';
  create.hidden=mode!=='create';
  sign.hidden=mode!=='signin';
  if(mode==='create')paintCreateFirm();
  create.querySelectorAll('input,select,button').forEach(node=>{if(node.type!=='button')node.disabled=mode!=='create'});
  sign.querySelectorAll('input,button').forEach(node=>{if(node.type!=='button')node.disabled=mode!=='signin'});
  const key=mode==='create'?'createProfile':mode==='signin'?'signInExisting':'gateTitle';
  if(title&&I18N[key]){title.dataset.i18n=key;title.textContent=I18N[key][state.lang==='en'?0:1]}
}
function enterRealtor(account,message){
  state.logo='';state.connections=[];state.channelMessages=[];state.tipSends=[];state.giftCards=[];state.giftLogo='';
  rememberRealtor(account);
  if(el('sessionNotice'))el('sessionNotice').hidden=true;
  loadTipStore().then(()=>render());
  state.loggedIn=true;
  state.reportReady=false;
  state.reportName='';
  state.reports=[];
  sessionStorage.removeItem('safe-realtor-reports');
  loadEstimate();
  localStorage.setItem('safe-demo-login','true');
  closeModals();
  applyAccessMode();
  const target=state.pendingRoute||'home';
  state.pendingRoute=null;
  navigate(target);
  toast(message);
}
function applyAccessMode(){
  document.body.classList.toggle('public-mode',!state.loggedIn);
  document.body.classList.toggle('tool-page',state.route!=='welcome');
  document.querySelectorAll('.member-only').forEach(node=>node.hidden=!state.loggedIn);
  document.querySelectorAll('.guest-only').forEach(node=>node.hidden=state.loggedIn);
  if(state.loggedIn){el('publicMenu')?.classList.remove('open');paintRealtor()}
  if(!state.loggedIn&&!publicRoutes.has(state.route))state.route='welcome';
}
function repairRange(r){
  if(!Number.isFinite(Number(r.low)))return t('Consultation required','Requiere consulta');
  if(Number(r.low)===Number(r.high))return `${money(r.low)}${r.unit?' / '+cat(r,'unit'):''}`;
  return `${money(r.low)}–${money(r.high)}`;
}
function catalogPair(r){
  const low=r.catalogLow!=null?Number(r.catalogLow):Number(r.low)||0;
  const high=r.catalogHigh!=null?Number(r.catalogHigh):Number(r.high)||low;
  return {low,high};
}
function rememberCatalogPrice(row){
  if(row.catalogLow==null)row.catalogLow=Number(row.low)||0;
  if(row.catalogHigh==null)row.catalogHigh=Number(row.high)||Number(row.low)||0;
}
function lowReason(r){
  const note=(r.notes?cat(r,'notes'):'').trim();
  return note?`${t('Standard scope','Alcance estándar')}: ${note}`:t('Standard scope in the catalog, before any review condition.','Alcance estándar del catálogo, antes de cualquier condición de revisión.');
}
function highReason(r){
  const pair=catalogPair(r);
  if(pair.low===pair.high)return t('The catalog uses one price for this service.','El catálogo usa un solo precio para este servicio.');
  const review=(r.review?cat(r,'review'):'').trim();
  const materials=(r.materials||'').trim();
  const parts=[];
  if(review)parts.push(`${t('Higher when this applies','Sube si aplica')}: ${review}.`);
  if(/separate/i.test(materials))parts.push(`${t('Not included in either price','No incluido en ninguno de los dos precios')}: ${cat(r,'materials')}.`);
  return parts.join(' ')||t('Upper end of the same service.','Tope del mismo servicio.');
}
function serviceTotals(){
  const low=state.estimate.reduce((s,r)=>s+(Number(r.low)||0),0);
  const high=state.estimate.reduce((s,r)=>s+(Number(r.high)||Number(r.low)||0),0);
  return {low,high:high||low,trip:Math.max(0,Number(state.transportAmount)||0)};
}
function optionMoney(key){
  const totals=serviceTotals();
  if(!totals.low&&!totals.trip)return '—';
  if(key==='minimum')return money(totals.low*.72+totals.trip);
  if(key==='complete')return money((totals.high||totals.low)*1.22+totals.trip);
  const start=totals.low+totals.trip,end=(totals.high||totals.low)+totals.trip;
  return start===end?money(start):`${money(start)}–${money(end)}`;
}
function paintOptionPrices(){
  ['minimum','recommended','complete'].forEach(key=>{const node=document.querySelector(`[data-option-price="${key}"]`);if(node)node.textContent=optionMoney(key)});
}
function negotiationText(){
  const lines=state.estimate.map(r=>`• ${cat(r,'service')}\n  ${t('Low price','Precio bajo')}: ${money(r.low)} — ${lowReason(r)}\n  ${t('High price','Precio alto')}: ${money(r.high||r.low)} — ${highReason(r)}`).join('\n');
  const trip=Math.max(0,Number(state.transportAmount)||0);
  return `${t('Price negotiation','Negociación de precios')}\n${lines}\n\n${t('Transportation','Transporte')} (${t('additional, not inside the service price','adicional, no va dentro del precio del servicio')}): ${money(trip)}`;
}
function negotiateLine(r){
  const pair=catalogPair(r);
  const low=lowReason(r),high=highReason(r);
  return `<div class="estimate-line negotiate"><div><strong>${esc(cat(r,'service'))}</strong><p>${esc(cat(r,'unit'))}</p><small>${t('Catalog','Catálogo')} ${money(pair.low)}${pair.high!==pair.low?`–${money(pair.high)}`:''}</small>${r.finding?`<small class="finding-note" title="${esc(r.finding)}">${t('From the inspection','De la inspección')}: ${esc(r.finding)}</small>`:''}</div><div class="price-pair"><label>${t('Low price','Precio bajo')}<input type="number" min="0" step="1" data-price-low="${esc(r.id)}" value="${Number(r.low)||0}"><small title="${esc(low)}">${esc(low)}</small></label><label>${t('High price','Precio alto')}<input type="number" min="0" step="1" data-price-high="${esc(r.id)}" value="${Number(r.high)||Number(r.low)||0}"><small title="${esc(high)}">${esc(high)}</small></label></div><button data-remove="${esc(r.id)}" aria-label="${t('Remove','Quitar')}">×</button></div>`;
}
function transportLine(){
  return `<div class="estimate-line negotiate transport-line"><div><strong>${t('Transportation','Transporte')}</strong><p>${t('Additional. It is not inside the low or high price of a service.','Adicional. No está dentro del precio bajo ni del alto de un servicio.')}</p></div><label class="trip-field">${t('Trip charge','Cargo de traslado')}<input type="number" min="0" step="1" id="transportAmount" value="${Number(state.transportAmount)||0}"><small>${t('Write it here when mileage, the visit or access equipment changes the price.','Escríbelo aquí cuando el kilometraje, la visita o el equipo de acceso cambian el precio.')}</small></label></div>`;
}
function addRepair(id){
  if(!state.loggedIn){state.pendingRoute='estimates';openModal('loginModal');return}
  const r=state.catalog.find(x=>x.id===id);if(!r)return;
  if(state.estimate.some(x=>x.id===id)){toast(t('Already in your estimate','Ya está en el estimado'));return}
  state.estimate.push({...r,qty:1});persistEstimate();toast(t('Repair added to estimate','Reparación agregada al estimado'));
}
function removeRepair(id){state.estimate=state.estimate.filter(x=>x.id!==id);persistEstimate();if(state.route==='estimates')render()}
function clearEstimate(){
  const n=state.estimate.length;if(!n)return;
  if(!confirm(t(`Remove all ${n} repairs from the estimate? This cannot be undone.`,`¿Quitar las ${n} reparaciones del estimado? No se puede deshacer.`)))return;
  state.estimate=[];state.repairOption='';state.transportAmount=0;persistEstimate();
  if(['estimates','search','report'].includes(state.route))render();
  toast(t('The estimate is empty','El estimado quedó vacío'));
}
function estimateBounds(){
  const low=state.estimate.reduce((s,r)=>s+(Number(r.low)||0),0);
  const high=state.estimate.reduce((s,r)=>s+(Number(r.high)||Number(r.low)||0),0);
  return {low,high:high||low};
}
function quoteText(option,client,address){
  const label=option==='minimum'?t('Minimum required repairs','Reparaciones mínimas'):option==='complete'?t('Complete property improvement','Mejora completa'):t('Recommended repair plan','Plan recomendado');
  const who=[state.account?.name,state.account?.firm===NO_FIRM?'':state.account?.firm].filter(Boolean).join(' · ');
  const lines=state.estimate.map(r=>`• ${cat(r,'service')}\n  ${t('Low price','Precio bajo')}: ${money(r.low)} — ${lowReason(r)}\n  ${t('High price','Precio alto')}: ${money(r.high||r.low)} — ${highReason(r)}`).join('\n');
  const trip=Math.max(0,Number(state.transportAmount)||0);
  return `${t('SAFE repair quote','Cotización de reparaciones SAFE')}${who?`\n${who}`:''}\n\n${t('For','Para')}: ${client||t('Client','Cliente')}\n${t('Property','Propiedad')}: ${address||t('Property address','Dirección')}\n\n${t('Repairs','Reparaciones')}\n${lines}\n\n${t('Transportation','Transporte')} (${t('additional','adicional')}): ${money(trip)}\n${t('Option','Opción')}: ${label}\n${t('Planning range','Rango preliminar')}: ${optionMoney(option==='minimum'?'minimum':option==='complete'?'complete':'recommended')}\n\n${t('The low price is the standard scope. The high price is the same service when the review condition applies. Transportation is extra. SAFE confirms the final price.','El precio bajo es el alcance estándar. El precio alto es el mismo servicio cuando aplica la condición de revisión. El transporte va aparte. SAFE confirma el precio final.')}`;
}
function refreshQuote(){
  if(!el('quotePreview'))return;
  el('quotePreview').textContent=quoteText(el('quoteOption')?.value||'recommended',el('quoteClient')?.value.trim(),el('quoteAddress')?.value.trim());
}
function syncQuoteSelect(){
  const sel=el('quoteOption');
  if(!sel)return;
  if(!sel.querySelector('option[value=""]')){
    const blank=document.createElement('option');
    blank.value='';
    blank.textContent=t('Choose an option','Elige una opción');
    sel.prepend(blank);
  }
  sel.value=state.repairOption||'';
}
function openQuote(option){
  if(!state.loggedIn){state.pendingRoute='estimates';openModal('loginModal');return}
  if(!state.estimate.length){toast(t('Add repairs before generating the quote.','Agrega reparaciones antes de generar la cotización.'));return}
  const chosen=option||state.repairOption||'recommended';
  state.repairOption=chosen;
  syncQuoteSelect();
  refreshQuote();
  openModal('quoteModal');
}
function drawerClearRow(){return `<div class="drawer-clear"><span>${state.estimate.length} ${t('repairs','reparaciones')}</span><button type="button" class="text-button danger" data-clear-estimate>${t('Remove all','Quitar todas')}</button></div>`}
function renderDrawer(){
  const body=el('estimateItems');
  if(!state.estimate.length)body.innerHTML=`<div class="empty-state"><div class="empty-icon">▤</div><h3>${t('No repairs selected','No hay reparaciones')}</h3><p>${t('Search the catalog and add repairs to build an estimate.','Busca en el catálogo y agrega reparaciones.')}</p></div>`;
  else body.innerHTML=drawerClearRow()+state.estimate.map(r=>`<div class="drawer-item"><div class="row"><strong>${esc(cat(r,'service'))}</strong><span class="price">${repairRange(r)}</span></div><small>${esc(state.lang==='en'?r.category:(categoryES[r.category]||r.category))}</small><br><button data-remove="${r.id}">${t('Remove','Quitar')}</button></div>`).join('');
  const low=state.estimate.reduce((s,r)=>s+(Number(r.low)||0),0),high=state.estimate.reduce((s,r)=>s+(Number(r.high)||Number(r.low)||0),0);
  el('estimateTotal').textContent=state.estimate.length?(low===high?money(low):`${money(low)}–${money(high)}`):'$0';
  body.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>removeRepair(b.dataset.remove));
  body.querySelectorAll('[data-clear-estimate]').forEach(b=>b.onclick=clearEstimate);
}

