function universalResults(query){
  const q=normalized(query);if(!q)return[];
  const terms=q.split(/\s+/).filter(Boolean);
  const modules=moduleIndex.map(m=>{const hay=normalized(m.slice(2).join(' '));const score=terms.reduce((s,x)=>s+(hay.includes(x)?6:0),0);return score?{type:'module',route:m[0],icon:m[1],title:t(m[2],m[3]),subtitle:t('Tool or CRM section','Herramienta o sección CRM'),score}:null}).filter(Boolean);
  const repairs=searchCatalog(query).slice(0,8).map(r=>({type:'repair',route:'search',icon:'$',title:cat(r,'service'),subtitle:`${t('Repair','Reparación')} · ${repairRange(r)}`,repair:r,score:r.score+2}));
  const hit=(fields,points)=>{const hay=normalized(fields.join(' '));return terms.reduce((s,x)=>s+(hay.includes(x)?points:0),0)};
  const people=(state.loggedIn?clientRows():[]).map(c=>{const score=hit([c.name,c.email,c.phone,c.address],5);return score?{type:'client',route:'clients',icon:initials(c.name||'C'),title:c.name,subtitle:[c.address,c.email,c.phone].filter(Boolean).join(' · ')||t('Client','Cliente'),score}:null}).filter(Boolean);
  const visits=(state.loggedIn?loadVisits():[]).map(v=>{const score=hit([v.client,v.address,v.note,v.date],4);return score?{type:'visit',route:'followups',icon:'□',title:v.client,subtitle:[v.date,v.time,v.address].filter(Boolean).join(' · '),score}:null}).filter(Boolean);
  const work=(state.loggedIn?jobs():[]).map(j=>{const score=hit([j.client,j.address,j.title,j.service,j.status],4);return score?{type:'job',route:'messages',icon:'◌',title:j.client||j.address||t('Job','Trabajo'),subtitle:[j.address,woStatusLabel(j.status||'')].filter(Boolean).join(' · '),score}:null}).filter(Boolean);
  const templates=monthlyTemplates.map(m=>{const hay=normalized([m.month,m.monthEs,m.title,m.titleEs,m.en,m.es].join(' '));const score=terms.reduce((s,x)=>s+(hay.includes(x)?4:0),0);return score?{type:'template',route:'campaigns',icon:'✦',title:t(m.title,m.titleEs),subtitle:t(m.month,m.monthEs),template:m,score}:null}).filter(Boolean);
  return [...modules,...repairs,...people,...visits,...work,...templates].sort((a,b)=>b.score-a.score).slice(0,12);
}
function showGlobalResults(query){
  const box=el('globalResults'),results=universalResults(query);
  if(!query.trim()){box.classList.remove('open');box.innerHTML='';return}
  box.innerHTML=results.length?results.map((r,i)=>`<button class="global-result ${i===0?'active':''}" data-global-route="${r.route}" data-global-query="${r.type==='repair'?esc(query):''}" data-template="${r.template?.id||''}"><span class="result-icon">${esc(r.icon)}</span><span><strong>${esc(r.title)}</strong><small>${esc(r.subtitle)}</small></span><small>${esc({module:t('Section','Sección'),repair:t('Repair','Reparación'),client:t('Client','Cliente'),visit:t('Visit','Visita'),job:t('Job','Trabajo'),template:t('Tip','Consejo')}[r.type]||r.type)}</small></button>`).join(''):`<div class="global-empty">${t('No result yet. Try a client, repair, report, message or schedule.','Sin resultados. Busca un cliente, reparación, reporte, mensaje o agenda.')}</div>`;
  box.classList.add('open');
  box.querySelectorAll('[data-global-route]').forEach(b=>b.onclick=()=>{if(b.dataset.globalQuery)state.query=b.dataset.globalQuery;if(b.dataset.template)localStorage.setItem('safe-active-template',b.dataset.template);el('globalSearch').value='';box.classList.remove('open');navigate(b.dataset.globalRoute)});
}
