function repairCard(r){
  const exact=String(r.automatic).toLowerCase()==='yes';
  const category=state.lang==='en'?r.category:(categoryES[r.category]||r.category);
  const terms=state.lang==='en'?r.customer_en:(catalogES[r.id]?.customer||r.customer_es);
  return `<article class="repair-card"><div><div class="repair-meta"><span class="tag aqua">${esc(category)}</span><span class="tag ${exact?'green':'gold'}">${exact?t('Instant range','Rango inmediato'):t('Management review','Revisión Management')}</span><span class="tag">${esc(cat(r,'tier'))}</span></div><h3>${esc(cat(r,'service'))}</h3><p>${esc(cat(r,'inspector')||cat(r,'notes'))}</p><p class="terms"><strong>${t('People also search:','También buscan:')}</strong> ${esc(terms)}</p></div><div class="repair-price"><strong>${repairRange(r)}</strong><small>${esc(cat(r,'pricing_model'))} · ${esc(cat(r,'unit'))}</small><button class="button ${state.estimate.some(x=>x.id===r.id)?'ghost':'primary'} small" data-add="${r.id}">${state.estimate.some(x=>x.id===r.id)?t('Added ✓','Agregado ✓'):t('Add to estimate','Agregar')}</button></div></article>`;
}

