function analysisView(){
  const reports=state.reports||[];
  const title=reports.length>1?t(`${reports.length} inspection reports`,`${reports.length} reportes de inspección`):((reports[0]&&reports[0].name)||t('Inspection report','Reporte de inspección'));
  const count=reports.reduce((sum,report)=>sum+(report.findings||[]).length,0);
  const summaryEn=count?`${count} findings simplified. Select what you want to quote.`:'No selectable text was found. Add another PDF or search the price guide.';
  const summaryEs=count?`${count} hallazgos simplificados. Elige lo que quieres cotizar.`:'No hay texto seleccionable. Agrega otro PDF o busca en la guía de precios.';
  const selected=state.estimate.length;
  const cards=reports.map(report=>{
    const findings=report.findings||[];
    const body=report.empty?`<p>${t('This PDF has no selectable text, so the findings could not be read. It stays in the list. Add another file or type the items from the price guide.','Este PDF no tiene texto seleccionable, así que no se pudieron leer los hallazgos. Sigue en la lista. Agrega otro archivo o escribe los ítems desde la guía de precios.')}</p>`:findings.length?findings.map(f=>`<label class="finding"><input type="checkbox" data-quote-finding="${esc(f.key)}" ${state.estimate.some(x=>x.id===f.estimateId)?'checked':''}><div><strong>${esc(f.catalogId?cat({id:f.catalogId,service:f.service},'service'):f.service)}</strong><p>${esc(f.detail)}</p><small>${esc(state.lang==='en'?f.category:(categoryES[f.category]||f.category))}</small></div><div class="finding-price"><span class="tag ${f.level==='Safety'?'red':f.level==='Priority'?'gold':'aqua'}">${esc(levelLabel(f.level))}</span><strong>${f.catalogId?repairRange(f):t('Price to define','Precio por definir')}</strong></div></label>`).join(''):`<p>${t('No repair findings were detected in this file.','No se detectaron hallazgos de reparación en este archivo.')}</p>`;
    return `<section class="card report-block"><div class="report-file"><div><span class="tag green">${t('Report uploaded','Reporte cargado')}</span><h2>${esc(report.name)}</h2><p>${findings.length?`${findings.length} ${t('findings','hallazgos')}`:t('Kept with the other reports','Conservado junto con los otros reportes')}</p></div><button class="button secondary small" type="button" data-drop-report="${esc(report.id)}">${t('Remove this file','Quitar este archivo')}</button></div><div class="finding-list">${body}</div></section>`;
  }).join('');
  return `${pageHead('REPORT ANALYZED',title,title,summaryEn,summaryEs,`<label class="button secondary">${t('Upload another','Subir otro')}<input id="addReportFile" type="file" accept="application/pdf,.pdf" multiple aria-hidden="true" tabindex="-1"></label>`)}
  <section class="card analysis-summary"><div class="analysis-head"><div><span class="eyebrow">${t('SIMPLIFIED FOR THE QUOTE','SIMPLIFICADO PARA COTIZAR')}</span><h2>${t('What the inspection is asking for','Lo que pide la inspección')}</h2><p>${t('Each line is one finding, in plain language, with the catalog price when there is a match. Check the ones to include in the quote.','Cada línea es un hallazgo, en lenguaje claro, con el precio del catálogo cuando hay coincidencia. Marca los que entran en la cotización.')}</p></div><div><span class="eyebrow">${t('SELECTED ITEMS','ÍTEMS SELECCIONADOS')}</span><strong id="selectedFindingCount" style="font-size:28px">${selected}</strong></div></div><div class="analysis-actions"><button class="button secondary" type="button" id="addMatchedFindings">${t('Add matched repairs','Agregar coincidencias')}</button><button class="button secondary" data-route="estimates">${t('Build the quote','Armar cotización')}</button><button class="button primary" data-action="new-request">${t('Send for SAFE review','Enviar a SAFE')}</button></div></section>
  <div class="report-stack">${cards}</div>`;
}
function levelLabel(level){
  if(level==='Safety')return t('Safety','Seguridad');
  if(level==='Priority')return t('Priority','Prioridad');
  if(level==='Review')return t('Needs review','Requiere revisión');
  return t('Routine','Rutina');
}

const PLAN_STEPS=[['Property','Propiedad'],['Sources','Fuentes'],['Findings','Hallazgos'],['Scope & cost','Alcance y costo'],['Pricing','Precios'],['Approval','Aprobación'],['Schedule','Agenda'],['Work & closeout','Trabajo y cierre']];
const PLAN_STAGES=[['Under contract / due diligence','Bajo contrato / periodo de revisión'],['Pre-listing','Antes de listar'],['After closing','Después del cierre']];
const PLAN_GOALS=[['Buyer repair negotiation','Negociación de reparaciones del comprador'],['Seller repair completion','Reparaciones del vendedor'],['Post-closing work','Trabajo después del cierre']];
const PLAN_WINDOWS=[['Morning · 8–12','Mañana · 8–12'],['Afternoon · 12–5','Tarde · 12–5'],['All day · 8–5','Todo el día · 8–5']];
const PLAN_STATUS={'Draft':['Draft','Borrador'],'Approval sent':['Sent for approval','Enviado para aprobación'],'Approved':['Client approved','Aprobado por el cliente'],'Sent to Management':['Sent to Management','Enviado a Management']};
const pairLabel=(list,value)=>{const row=list.find(x=>x[0]===value);return row?t(row[0],row[1]):value||''};
function planDraftKey(){return state.account?.email?`safe-repair-plan:${state.account.email.toLowerCase()}`:''}
function newPlan(){return {id:0,clientName:'',clientEmail:'',address:'',stage:PLAN_STAGES[0][0],targetClose:'',goal:PLAN_GOALS[0][0],items:[],pricing:'fixed',hourlyRate:Number(state.planSettings.hourlyRate)||0,credit:0,maxAuthorization:0,preferredDate:'',preferredWindow:PLAN_WINDOWS[0][0],accessNotes:'',status:'Draft',requestId:'',step:1}}
function currentPlan(){
  if(!state.plan){try{state.plan=JSON.parse(localStorage.getItem(planDraftKey())||'null')}catch{}if(!state.plan)state.plan=newPlan()}
  return state.plan;
}
function keepPlanDraft(){if(planDraftKey()&&state.plan)localStorage.setItem(planDraftKey(),JSON.stringify(state.plan))}
const perArea=unit=>/sq ft|linear ft/i.test(unit||'');
function planItemFrom(r){
  const c=state.catalog.find(x=>x.id===r.id);
  const src=c||r;
  const low=r.low==null||!Number.isFinite(Number(r.low))?null:Number(r.low);
  const high=low==null?null:Number(r.high??r.low)||low;
  return {id:r.id,service:src.service||'',category:src.category||'',qty:perArea(src.unit)?100:1,unit:src.unit||'',techHours:c?(Number(c.hours)||0)*(Number(c.techs)||1):0,low,high,materials:src.materials||'',pricingModel:src.pricing_model||'',finding:r.finding||'',quote:low==null||/quote|consult/i.test(src.pricing_model||'')};
}
function planCatalogRow(i){return state.catalog.find(x=>x.id===i.id)||null}
function planItemName(i){const c=planCatalogRow(i);return c?cat(c,'service'):i.service}
function planItemUnit(i){const c=planCatalogRow(i);return c?cat(c,'unit'):i.unit}
function planItemMaterials(i){const c=planCatalogRow(i);return c?cat(c,'materials'):i.materials}
function materialKind(i){const m=i.materials||'';return /includ/i.test(m)?'included':/separate/i.test(m)?'separate':'confirm'}
function planItemHours(i){return perArea(i.unit)?i.techHours:i.techHours*(Number(i.qty)||1)}
function planItemSpan(i){
  const c=planCatalogRow(i),n=v=>v==null||v===''||!Number.isFinite(Number(v))?null:Number(v);
  const q=Number(i.qty)||1,jobs=perArea(i.unit)?1:q,base=Number(i.techHours)||0;
  const hl=n(c?.hours_low)??base,hh=Math.max(hl,n(c?.hours_high)??n(i.techHoursHigh)??Math.max(base,hl));
  const ml=n(c?.materials_low)??n(c?.materials_high)??n(i.materialsLow),mh=ml==null?null:Math.max(ml,n(c?.materials_high)??n(i.materialsHigh)??ml);
  return {hoursLow:hl*jobs,hoursHigh:hh*jobs,perJobHigh:hh,matUnitLow:ml,matUnitHigh:mh,matLow:ml==null?null:ml*q,matHigh:mh==null?null:mh*q};
}
const hoursText=(a,b)=>`${a===b?a:`${a}–${b}`} hr`;
function planRollup(p=currentPlan()){
  const s=state.planSettings,r={hoursLow:0,hoursHigh:0,low:0,high:0,priced:0,quote:0,undefinedPrice:0,units:0,included:0,separate:0,confirm:0,matLow:0,matHigh:0,matPriced:0};
  p.items.forEach(i=>{const q=Number(i.qty)||1,sp=planItemSpan(i);r.units+=q;r.hoursLow+=sp.hoursLow;r.hoursHigh+=sp.hoursHigh;if(sp.matLow!=null){r.matLow+=sp.matLow;r.matHigh+=sp.matHigh;r.matPriced++}if(i.low==null)r.undefinedPrice++;else{r.low+=i.low*q;r.high+=(i.high??i.low)*q;r.priced++}if(i.quote)r.quote++;r[materialKind(i)]++});
  r.rate=Number(p.hourlyRate)||Number(s.hourlyRate)||0;
  r.hourlyLow=Math.round(r.hoursLow*r.rate);r.hourly=Math.round(r.hoursHigh*r.rate);
  r.days=Math.max(1,Math.ceil(r.hoursHigh/(Number(s.repairDayHours)||8)));
  r.dayLow=(Number(s.repairDayLow)||0)*r.days;r.dayHigh=(Number(s.repairDayHigh)||0)*r.days;
  r.hoursLow=Math.round(r.hoursLow*10)/10;r.hoursHigh=Math.round(r.hoursHigh*10)/10;r.hours=r.hoursHigh;
  r.hoursText=hoursText(r.hoursLow,r.hoursHigh);
  r.materialsText=r.matPriced?rangeText(Math.round(r.matLow),Math.round(r.matHigh)):'';
  return r;
}
function planOptionRange(p,r=planRollup(p)){return p.pricing==='hourly'?[r.hourlyLow,r.hourly]:p.pricing==='day'?[r.dayLow,r.dayHigh]:[r.low,r.high]}
function planMaxDefault(p,r){return planOptionRange(p,r)[1]}
function planOptionLabel(p){return p.pricing==='hourly'?t('Pay by the hour','Pago por hora'):p.pricing==='day'?'SAFE Repair Day':t('Fixed price','Precio fijo')}
const rangeText=(a,b)=>a===b?money(a):`${money(a)}–${money(b)}`;
function planClientCredits(p){
  const name=(p.clientName||'').trim().toLowerCase(),address=(p.address||'').trim().toLowerCase();
  return (state.giftCards||[]).filter(g=>(name&&String(g.clientName||'').trim().toLowerCase()===name)||(address&&String(g.address||'').trim().toLowerCase()===address));
}
function planSummaryText(p){
  const r=planRollup(p),[a,b]=planOptionRange(p,r),credit=Number(p.credit)||0;
  const lines=p.items.map(i=>`• ${planItemName(i)} — ${Number(i.qty)||1} ${planItemUnit(i)} · ${i.low==null?t('price to be defined by SAFE','precio por definir por SAFE'):rangeText(i.low*(Number(i.qty)||1),(i.high??i.low)*(Number(i.qty)||1))}${i.quote&&i.low!=null?' · '+t('Management confirms','Management confirma'):''}`).join('\n');
  const who=[state.account?.name,state.account?.firm&&state.account.firm!==NO_FIRM?state.account.firm:''].filter(Boolean).join(' · ');
  return `${t('SAFE repair plan','Plan de reparaciones SAFE')}${who?`\n${who}`:''}\n\n${t('Client','Cliente')}: ${p.clientName}\n${t('Property','Propiedad')}: ${p.address}\n\n${t('Repairs','Reparaciones')}\n${lines}\n\n${t('Technician time','Tiempo técnico')}: ${r.hoursText}\n${r.matPriced?`${t('Estimated materials','Materiales estimados')}: ${r.materialsText}\n`:''}${t('Option','Opción')}: ${planOptionLabel(p)} · ${rangeText(a,b)}\n${credit?`${t('Credit','Crédito')}: −${money(credit)}\n${t('Estimated after credit','Estimado después del crédito')}: ${rangeText(Math.max(0,a-credit),Math.max(0,b-credit))}\n`:''}${t('Maximum authorization','Autorización máxima')}: ${money(Number(p.maxAuthorization)||planMaxDefault(p,r))}\n\n${t('Materials are listed per repair. SAFE confirms the final scope and price before any work starts.','Los materiales se indican por reparación. SAFE confirma el alcance y precio final antes de comenzar.')}`;
}
async function savePlan(showError=false){
  const p=currentPlan();keepPlanDraft();
  if(!p.address||!p.clientName)return false;
  try{
    const response=await fetch('/api/realtor/repair-plans',{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify({...p,id:p.id||null,realtorEmail:state.account?.email||'',items:p.items.map(i=>{const s=planItemSpan(i);return {...i,techHoursHigh:s.perJobHigh,materialsLow:s.matUnitLow,materialsHigh:s.matUnitHigh}})})});
    const body=await response.json().catch(()=>({}));
    if(!response.ok)throw new Error((state.lang==='es'&&body.errorEs)||body.error||'');
    p.id=body.id;keepPlanDraft();
    state.plans=[body,...(state.plans||[]).filter(x=>x.id!==body.id)];
    return true;
  }catch(e){if(showError)toast(e.message||t('The plan stays in this browser; the database could not save it.','El plan queda en este navegador; la base de datos no lo pudo guardar.'));return false}
}
function planCandidates(p){
  const map=new Map();
  state.estimate.forEach(r=>map.set(r.id,{row:r,from:r.finding?'report':'estimate'}));
  p.items.forEach(i=>{if(!map.has(i.id))map.set(i.id,{item:i,from:'plan'})});
  return [...map.values()];
}
function planSearchHtml(){
  const q=state.planQuery.trim();
  if(!q)return '';
  const p=currentPlan();
  const rows=searchCatalog(q).slice(0,6);
  return rows.length?rows.map(r=>`<div><span><strong>${esc(cat(r,'service'))}</strong><small>${esc(state.lang==='en'?r.category:(categoryES[r.category]||r.category))} · ${repairRange(r)}</small></span>${p.items.some(i=>i.id===r.id)?`<span class="tag green">${t('In the plan','En el plan')}</span>`:`<button class="button secondary small" type="button" data-plan-add="${esc(r.id)}">+ ${t('Add','Agregar')}</button>`}</div>`).join(''):`<small>${t('No match. Try other words.','Sin coincidencias. Prueba otras palabras.')}</small>`;
}
function repairPlanView(){
  const p=currentPlan(),r=planRollup(p);
  const picker=(state.plans||[]).length?`<span class="plan-picker"><select id="planPicker" aria-label="${t('Saved plans','Planes guardados')}"><option value="">${t('Saved plans','Planes guardados')}</option>${state.plans.map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${esc(x.address)} · ${esc(x.clientName)} · ${esc(t(PLAN_STATUS[x.status]?.[0]||x.status,PLAN_STATUS[x.status]?.[1]||x.status))}</option>`).join('')}</select></span>`:'';
  return `${pageHead(t('BUILD MY REPAIR PLAN','CREAR MI PLAN DE REPARACIONES'),'Repair cost & labor estimator','Estimador de costo y mano de obra','Handyman and trade planning: compare technician time, materials, hourly labor and fixed price before the work is approved.','Planificación de mantenimiento general y especialidades: compara tiempo técnico, materiales, mano de obra por hora y precio fijo antes de aprobar el trabajo.',`${picker}<button class="button secondary" id="planNew">+ ${t('New plan','Nuevo plan')}</button>`)}
  <section class="plan-shell">
    <div class="estimator-bar"><div><span class="eyebrow">${t('HANDYMAN & TRADE REPAIR PLANNING','PLANIFICACIÓN DE MANTENIMIENTO GENERAL Y ESPECIALIDADES')}</span><strong>${t('One scope. Four price signals.','Un alcance. Cuatro señales de precio.')}</strong></div><div class="estimator-mini"><span><small>${t('Technician time','Tiempo técnico')}</small><b>${r.hoursText}</b></span><span><small>${t('Materials','Materiales')}</small><b>${r.materialsText||`${r.separate} ${t('separate','aparte')} · ${r.included} ${t('included','incluidos')}`}</b></span><span><small>${t('Hourly labor','Mano de obra por hora')}</small><b>${rangeText(r.hourlyLow,r.hourly)}</b></span><span><small>${t('Fixed price / job','Precio fijo / trabajo')}</small><b>${rangeText(r.low,r.high)}</b></span></div></div>
    <div class="plan-progress">${PLAN_STEPS.map((s,i)=>`<button type="button" class="${p.step===i+1?'active':''} ${p.step>i+1?'done':''}" data-plan-step="${i+1}"><span>${p.step>i+1?'✓':i+1}</span><small>${t(s[0],s[1])}</small></button>`).join('')}</div>
    <div class="plan-workspace">${planStepContent(p,r)}</div>
    <footer class="plan-footer"><div><strong>${p.items.length} ${t('repair types','tipos de reparación')} · ${t(PLAN_STATUS[p.status]?.[0]||p.status,PLAN_STATUS[p.status]?.[1]||p.status)}</strong><small>${r.hoursText.replace(' hr','')} ${t('technician-hours','horas-técnico')}${r.matPriced?` · ${r.materialsText} ${t('materials','materiales')}`:''} · ${t('fixed','fijo')} ${rangeText(r.low,r.high)}${p.id?` · ${t('Saved','Guardado')} #${p.id}`:''}</small></div><div><button class="button secondary" type="button" data-plan-prev ${p.step===1?'disabled':''}>${t('Back','Atrás')}</button>${p.step<8?`<button class="button primary" type="button" data-plan-next>${t('Continue','Continuar')}</button>`:''}</div></footer>
  </section>`;
}
function planStepContent(p,r){
  const intro=(step,en,es,descEn,descEs,side='')=>`<div class="plan-intro"><div><span class="eyebrow">${t('STEP','PASO')} ${step} · ${t(PLAN_STEPS[step-1][0],PLAN_STEPS[step-1][1]).toUpperCase()}</span><h2>${t(en,es)}</h2><p>${t(descEn,descEs)}</p></div>${side}</div>`;
  if(p.step===1){
    const opts=(list,value)=>list.map(x=>`<option value="${esc(x[0])}" ${x[0]===value?'selected':''}>${esc(t(x[0],x[1]))}</option>`).join('');
    return intro(1,'Start with the client and property','Comienza con el cliente y la propiedad','Every step of the plan stays tied to this property.','Cada paso del plan queda ligado a esta propiedad.')+`<div class="plan-form card-flat"><label>${t('Client','Cliente')}<input id="planClient" list="planClientList" value="${esc(p.clientName)}" autocomplete="off"><datalist id="planClientList">${clientRows().map(c=>`<option value="${esc(c.name)}"></option>`).join('')}</datalist></label><label>${t('Client email','Correo del cliente')}<input id="planClientEmail" type="email" value="${esc(p.clientEmail)}" placeholder="${t('name@email.com','nombre@correo.com')}"></label><label class="full">${t('Property address','Dirección de la propiedad')}<input id="planAddress" value="${esc(p.address)}" autocomplete="street-address"></label><label>${t('Transaction stage','Etapa de la transacción')}<select id="planStage">${opts(PLAN_STAGES,p.stage)}</select></label><label>${t('Target closing date','Fecha objetivo de cierre')}<input id="planClose" type="date" value="${esc(p.targetClose)}"></label><label>${t('Primary goal','Objetivo principal')}<select id="planGoal">${opts(PLAN_GOALS,p.goal)}</select></label><div class="plan-realtor"><span class="field-title">Realtor</span><div class="plan-realtor-row"><strong>${esc([state.account?.name,state.account?.firm&&state.account.firm!==NO_FIRM?state.account.firm:''].filter(Boolean).join(' · '))}</strong><button class="button secondary small" type="button" data-route="profile">${t('Change in My profile','Cambiar en Mi perfil')}</button></div></div></div>`;
  }
  if(p.step===2){
    const reports=state.reports||[],findings=reports.reduce((s,x)=>s+(x.findings||[]).length,0);
    return intro(2,'Add every source once','Agrega cada fuente una sola vez','Use the inspection report and the repairs you already chose. You pick the ones for this plan in the next step.','Usa el reporte de inspección y las reparaciones que ya elegiste. En el siguiente paso eliges las que van en este plan.')+`<div class="source-grid"><button type="button" class="source-card ${reports.length?'selected':''}" data-route="report"><span>PDF</span><strong>${t('Inspection report','Reporte de inspección')}</strong><small>${reports.length?`${esc(reports.map(x=>x.name).join(' · '))} · ${findings} ${t('findings','hallazgos')}`:t('No report yet. Upload it in Review inspection.','Aún no hay reporte. Súbelo en Revisar inspección.')}</small></button><button type="button" class="source-card ${state.estimate.length?'selected':''}" data-route="search"><span>$</span><strong>${t('Repairs from the price guide','Reparaciones de la guía de precios')}</strong><small>${state.estimate.length} ${t('repairs selected','reparaciones elegidas')}</small></button><div class="source-card"><span>＋</span><strong>${t('Manual repair','Reparación manual')}</strong><small>${t('Search the catalog in the next step and add what is missing.','Busca en el catálogo en el siguiente paso y agrega lo que falte.')}</small></div></div>`;
  }
  if(p.step===3){
    const rows=planCandidates(p).map(({row,item})=>{
      const i=item||planItemFrom(row),on=p.items.some(x=>x.id===i.id),c=planCatalogRow(i);
      const tags=[`<span class="tag aqua">${esc(state.lang==='en'?i.category:(categoryES[i.category]||i.category))}</span>`,i.low==null?`<span class="tag gold">${t('Price to define','Precio por definir')}</span>`:i.quote?`<span class="tag navy">${t('Management quote','Cotiza Management')}</span>`:''].join('');
      return `<label class="plan-finding ${on?'selected':''}"><input type="checkbox" data-plan-pick="${esc(i.id)}" ${on?'checked':''}><div><div class="repair-meta">${tags}</div><strong>${esc(planItemName(i))}</strong>${i.finding?`<p class="finding-note">${t('From the inspection','De la inspección')}: ${esc(i.finding)}</p>`:c?`<p>${esc(cat(c,'notes'))}</p>`:''}</div><div class="finding-side"><span>${i.techHours} hr · ${esc(planItemUnit(i))}</span><strong>${i.low==null?'—':rangeText(i.low,i.high??i.low)}</strong></div></label>`;
    }).join('');
    return intro(3,'Review and select the repairs','Revisa y selecciona las reparaciones','They come from your inspection review and your price guide picks. Nothing goes to a provider until the client approves.','Vienen de tu revisión de inspección y de la guía de precios. Nada se envía a un proveedor hasta que el cliente apruebe.',`<span class="tag green">${p.items.length} ${t('in the plan','en el plan')}</span>`)+`<div class="finding-board">${rows||`<div class="policy">${t('There are no repairs yet. Search the catalog below or review the inspection report.','Aún no hay reparaciones. Busca en el catálogo abajo o revisa el reporte de inspección.')}</div>`}</div><div class="plan-add"><strong>${t('Add a repair from the catalog','Agregar una reparación del catálogo')}</strong><div class="search-box"><span>⌕</span><input id="planSearch" value="${esc(state.planQuery)}" placeholder="${t('Describe the repair or paste the inspector wording','Describe la reparación o pega el texto del inspector')}"></div><div class="plan-add-results" id="planAddResults">${planSearchHtml()}</div></div>`;
  }
  if(p.step===4){
    const rows=p.items.map(i=>{const q=Number(i.qty)||1,sp=planItemSpan(i),hl=Math.round(sp.hoursLow*10)/10,hh=Math.round(sp.hoursHigh*10)/10,mk=materialKind(i);return `<div class="estimate-matrix-row"><div data-label="${t('Repair','Reparación')}"><strong>${esc(planItemName(i))}</strong><small>${esc(state.lang==='en'?i.category:(categoryES[i.category]||i.category))}${i.quote?' · '+t('Management confirms','Management confirma'):''}</small></div><label data-label="${t('Qty / unit','Cant. / unidad')}"><input type="number" min="1" max="10000" step="1" value="${q}" data-plan-qty="${esc(i.id)}" aria-label="${t('Quantity','Cantidad')} ${esc(planItemName(i))}"><small>${esc(planItemUnit(i))}</small></label><span data-label="${t('Technician time','Tiempo técnico')}">${hoursText(hl,hh)}</span><span data-label="${t('Materials','Materiales')}">${sp.matLow!=null?`<strong>${rangeText(Math.round(sp.matLow),Math.round(sp.matHigh))}</strong>`:`<span class="tag ${mk==='included'?'green':mk==='separate'?'gold':''}">${mk==='included'?t('Included','Incluido'):mk==='separate'?t('Separate','Aparte'):t('To confirm','Por confirmar')}</span>`}<small style="display:block">${esc(planItemMaterials(i))}</small></span><span data-label="${t('Hourly labor','Mano de obra por hora')}">${rangeText(Math.round(hl*r.rate),Math.round(hh*r.rate))}</span><strong data-label="${t('Fixed price / job','Precio fijo / trabajo')}">${i.low==null?t('To define','Por definir'):rangeText(i.low*q,(i.high??i.low)*q)}</strong></div>`}).join('');
    return intro(4,'Set quantity and compare every repair','Define cantidad y compara cada reparación','Each line keeps technician time, materials, hourly labor and fixed price separate.','Cada línea mantiene separados el tiempo técnico, los materiales, la mano de obra por hora y el precio fijo.')+`<div class="estimator-summary"><article><small>${t('Estimated technician time','Tiempo técnico estimado')}</small><strong>${r.hoursText}</strong><span>${t('Technician-hours, not elapsed time','Horas-técnico, no tiempo transcurrido')}</span></article><article><small>${t('Estimated materials','Materiales estimados')}</small><strong>${r.materialsText||`${r.separate} ${t('separate','aparte')}`}</strong><span>${r.matPriced?(r.matPriced<p.items.length?t(`${r.matPriced} of ${p.items.length} repairs have a materials cost`,`${r.matPriced} de ${p.items.length} reparaciones tienen costo de materiales`):t('Allowance range from the catalog','Rango de referencia del catálogo')):`${r.included} ${t('included','incluidos')} · ${r.confirm} ${t('to confirm','por confirmar')}`}</span></article><article><small>${t('Estimated hourly labor','Estimado de mano de obra por hora')}</small><strong>${rangeText(r.hourlyLow,r.hourly)}</strong><span>${money(r.rate)}/hr × ${r.hoursText}</span></article><article><small>${t('Fixed price / job','Precio fijo / trabajo')}</small><strong>${rangeText(r.low,r.high)}</strong><span>${t('Catalog range, materials apart when marked','Rango del catálogo, materiales aparte cuando se indica')}</span></article></div><div class="estimate-matrix"><div class="estimate-matrix-row matrix-head"><span>${t('Repair','Reparación')}</span><span>${t('Qty / unit','Cant. / unidad')}</span><span>${t('Technician time','Tiempo técnico')}</span><span>${t('Materials','Materiales')}</span><span>${t('Hourly labor','Mano de obra por hora')}</span><span>${t('Fixed price / job','Precio fijo / trabajo')}</span></div>${rows}</div><div class="formula-strip"><div><strong>${t('Hourly','Por hora')}</strong><code>${t('quantity × technician-hours × hourly rate','cantidad × horas-técnico × tarifa por hora')}</code></div><div><strong>${t('Fixed','Fijo')}</strong><code>${t('quantity × catalog price','cantidad × precio del catálogo')}</code></div><div><strong>${t('Per square / linear foot','Por pie cuadrado / lineal')}</strong><code>${t('price × feet; time is per job','precio × pies; el tiempo es por trabajo')}</code></div></div>${r.quote||r.undefinedPrice?`<div class="policy section-gap">${r.quote?t(`${r.quote} repairs need a Management quote; their range is a reference.`,`${r.quote} reparaciones necesitan cotización de Management; su rango es referencia.`):''} ${r.undefinedPrice?t(`${r.undefinedPrice} have no catalog price yet and are not in the totals.`,`${r.undefinedPrice} aún no tienen precio del catálogo y no entran en los totales.`):''}</div>`:''}`;
  }
  if(p.step===5){
    const max=Number(p.maxAuthorization)||planMaxDefault(p,r),dayHours=Number(state.planSettings.repairDayHours)||8;
    const choice=(key,small,title,price,detail,total)=>`<button type="button" class="pricing-choice ${p.pricing===key?'selected':''}" data-plan-pricing="${key}"><span class="choice-radio"></span><small>${small}</small><h3>${title}</h3><div class="big-price">${price}</div><p>${detail}</p><span class="project-total">${total}</span></button>`;
    return intro(5,'Let the client choose how to authorize the work','Deja que el cliente elija cómo autorizar el trabajo','Only the labor model changes; materials stay as marked on each repair.','Solo cambia el modelo de labor; los materiales quedan como se indican en cada reparación.')+`<div class="pricing-grid">${choice('fixed',t('BEST FOR CERTAINTY','MEJOR PARA CERTEZA'),t('Fixed price','Precio fijo'),rangeText(r.low,r.high),t('Catalog price per job, by quantity.','Precio del catálogo por trabajo, según cantidad.'),`${r.priced} ${t('priced repairs','reparaciones con precio')}`)}${choice('hourly',t('BEST FOR FLEXIBILITY','MEJOR PARA FLEXIBILIDAD'),t('Pay by the hour','Pago por hora'),rangeText(r.hourlyLow,r.hourly),`${money(r.rate)}/hr · ${r.hoursText}`,t('Capped by the maximum authorization','Con tope en la autorización máxima'))}${choice('day',t('BEST FOR SMALL REPAIRS','MEJOR PARA TRABAJOS PEQUEÑOS'),'SAFE Repair Day',rangeText(r.dayLow,r.dayHigh),t(`Up to ${dayHours} technician-hours per day · materials additional`,`Hasta ${dayHours} horas-técnico por día · materiales adicionales`),r.days>1?t(`This scope needs ${r.days} days`,`Este alcance necesita ${r.days} días`):t('This scope fits one day','Este alcance cabe en un día'))}</div><div class="rate-control"><div><strong>${t('Planning hourly rate','Tarifa por hora para planificar')}</strong><p>${t('Set by SAFE Management.','La define SAFE Management.')}</p></div><label>${money(r.rate)} / hr</label></div><div class="pricing-protection"><div><strong>${t('Maximum authorization','Autorización máxima')}</strong><p>${t('No work above this amount without a change order.','No se trabaja por encima de este monto sin una orden de cambio.')}</p></div><label>$ <input type="number" min="0" step="1" id="planMax" value="${Math.round(max)}"></label></div>`;
  }
  if(p.step===6){
    const [a,b]=planOptionRange(p,r),credit=Number(p.credit)||0,credits=planClientCredits(p);
    const creditRow=(amount,title,sub,on)=>`<label class="credit-row"><input type="radio" name="planCredit" data-plan-credit="${amount}" ${on?'checked':''}><span><strong>${title}</strong><small>${sub}</small></span><b>${amount?'−'+money(amount):'$0'}</b></label>`;
    return intro(6,'Apply credits and collect approval','Aplica créditos y recibe la aprobación','The client sees scope, price range and next step, never internal costs.','El cliente ve el alcance, el rango de precio y el siguiente paso, nunca costos internos.',`<span class="tag ${p.status==='Draft'?'':'green'}">${t(PLAN_STATUS[p.status][0],PLAN_STATUS[p.status][1])}</span>`)+`<div class="approval-layout"><section class="card-flat"><h3>${t('Credits for this client','Créditos de este cliente')}</h3>${creditRow(0,t('No credit','Sin crédito'),t('Use the price as shown','Usar el precio tal como está'),!credit)}${credits.map(g=>creditRow(Number(g.amount)||0,`${t('Gift card','Tarjeta de regalo')} ${esc(g.code)}`,esc([g.clientName,g.address].filter(Boolean).join(' · ')),credit===Number(g.amount))).join('')}${credits.length?'':`<p class="policy">${t('This client has no gift card yet. Create one in Gift cards and it shows here.','Este cliente aún no tiene tarjeta de regalo. Créala en Tarjetas de regalo y aparece aquí.')}</p>`}</section><section class="client-summary"><span class="eyebrow">${t('CLIENT SUMMARY','RESUMEN PARA EL CLIENTE')}</span><h3>${esc(p.address)}</h3><div class="summary-row"><span>${t('Repairs','Reparaciones')}</span><b>${p.items.length}</b></div><div class="summary-row"><span>${t('Option','Opción')}</span><b>${planOptionLabel(p)}</b></div><div class="summary-row"><span>${t('Price range','Rango de precio')}</span><b>${rangeText(a,b)}</b></div><div class="summary-row credit"><span>${t('Credit','Crédito')}</span><b>−${money(credit)}</b></div><div class="summary-total"><span>${t('Estimated after credit','Estimado después del crédito')}</span><strong>${rangeText(Math.max(0,a-credit),Math.max(0,b-credit))}</strong></div><button class="button primary wide" type="button" id="planSendApproval" ${p.status==='Sent to Management'?'disabled':''}>${p.status==='Approval sent'?t('Send to the client again','Enviar de nuevo al cliente'):t('Send to the client for approval','Enviar al cliente para aprobación')}</button><button class="button secondary wide" type="button" id="planApproved" style="margin-top:8px" ${p.status==='Approved'||p.status==='Sent to Management'?'disabled':''}>${p.status==='Approved'||p.status==='Sent to Management'?t('Client approved ✓','Cliente aprobó ✓'):t('The client approved','El cliente aprobó')}</button></section></div>`;
  }
  if(p.step===7){
    const sent=p.status==='Sent to Management';
    return intro(7,'Ask Management for the crew day','Pide a Management el día del equipo','You choose the preferred date and access. Management confirms workers, route and materials.','Tú eliges la fecha preferida y el acceso. Management confirma trabajadores, ruta y materiales.')+`<div class="schedule-handoff"><section class="plan-form card-flat"><label>${t('Preferred date','Fecha preferida')}<input type="date" id="planDate" min="${todayLocal()}" value="${esc(p.preferredDate)}" ${sent?'disabled':''}></label><label>${t('Time window','Horario')}<select id="planWindow" ${sent?'disabled':''}>${PLAN_WINDOWS.map(x=>`<option value="${esc(x[0])}" ${x[0]===p.preferredWindow?'selected':''}>${esc(t(x[0],x[1]))}</option>`).join('')}</select></label><label class="full">${t('Property access','Acceso a la propiedad')}<textarea id="planAccess" maxlength="1000" placeholder="${t('Who opens, pets, parking, call before arriving…','Quién abre, mascotas, parqueo, llamar antes de llegar…')}" ${sent?'disabled':''}>${esc(p.accessNotes)}</textarea></label></section><aside class="dispatch-card"><span class="tag ${sent?'green':p.status==='Approved'?'aqua':'gold'}">${sent?t('SENT TO MANAGEMENT','ENVIADO A MANAGEMENT'):p.status==='Approved'?t('READY FOR MANAGEMENT','LISTO PARA MANAGEMENT'):t('WAITING FOR CLIENT APPROVAL','ESPERANDO APROBACIÓN DEL CLIENTE')}</span><h3>${t('What Management receives','Lo que recibe Management')}</h3><ul><li>${t('Property','Propiedad')}: ${esc(p.address)}</li><li>${t('Repairs','Reparaciones')}: ${p.items.length}</li><li>${t('Technician time','Tiempo técnico')}: ${r.hoursText}</li>${r.matPriced?`<li>${t('Estimated materials','Materiales estimados')}: ${r.materialsText}</li>`:''}<li>${t('Option','Opción')}: ${planOptionLabel(p)}</li><li>${t('Maximum authorization','Autorización máxima')}: ${money(Number(p.maxAuthorization)||planMaxDefault(p,r))}</li>${p.requestId?`<li>${t('Request','Solicitud')}: ${esc(p.requestId)}</li>`:''}</ul><button class="button primary wide" type="button" id="planDispatch" ${sent?'disabled':''}>${sent?t('Sent to Management ✓','Enviado a Management ✓'):t('Send to Management','Enviar a Management')}</button></aside></div>`;
  }
  const req=(state.hub?.requests||[]).find(x=>x.id===p.requestId);
  const work=p.requestId?jobs().filter(j=>j.requestId===p.requestId):[];
  const done=work.some(j=>Number(j.progress)>=100||/complet|done|closed/i.test(j.status||''));
  const steps=[[!!p.requestId,t('Plan sent to Management','Plan enviado a Management')],[!!req&&!/^new$/i.test(req.status||''),t('Management reviewed it','Management lo revisó')],[work.length>0,t('Crew assigned','Equipo asignado')],[work.some(j=>j.checkInAt||/arriv|progress/i.test(j.status||'')),t('Worker arrived','Trabajador llegó')],[done,t('Work finished','Trabajo terminado')]];
  const timeline=work.length?work.map(j=>`<div><time>${esc(j.checkInAt?new Date(j.checkInAt).toLocaleTimeString(state.lang==='en'?'en-US':'es-US',{hour:'numeric',minute:'2-digit'}):'—')}</time><span></span><div><strong>${esc(j.worker&&j.worker!=='Unassigned'?j.worker:t('Crew','Equipo'))} · ${esc(woStatusLabel(j.status))}</strong><p>${esc(scopeLabel(j.scope)||j.address||'')} · ${Number(j.progress)||0}%</p></div></div>`).join(''):`<div class="policy">${p.requestId?t('Management has not assigned a crew yet. This updates by itself.','Management aún no asigna equipo. Esto se actualiza solo.'):t('Send the plan to Management in the Schedule step.','Envía el plan a Management en el paso Agenda.')}</div>`;
  return intro(8,'From the approved plan to the crew day','Del plan aprobado al día del equipo','You follow the same request Management and the worker use.','Sigues la misma solicitud que usan Management y el trabajador.',p.requestId?`<span class="data-object">${esc(p.requestId)}${req?' · '+esc(req.status):''}</span>`:'')+`<div class="field-board"><section class="worker-day"><header><div><strong>${t('Crew activity','Actividad del equipo')}</strong></div><span class="tag ${work.length?'green':'gold'}">${work.length?t(`${work.length} work orders`,`${work.length} órdenes de trabajo`):t('Waiting','En espera')}</span></header><div class="day-timeline">${timeline}</div></section><section class="closeout-card"><h3>${t('Progress','Avance')}</h3>${steps.map(([ok,label])=>`<div class="step-row ${ok?'done':''}"><b>${ok?'✓':'·'}</b><span>${label}</span></div>`).join('')}<button class="button secondary" type="button" data-route="messages">${t('Open job messages','Abrir mensajes del trabajo')}</button></section></div>`;
}
function planReadForm(p){
  if(el('planClient'))p.clientName=el('planClient').value.trim();
  if(el('planClientEmail'))p.clientEmail=el('planClientEmail').value.trim();
  if(el('planAddress'))p.address=el('planAddress').value.trim();
  if(el('planStage'))p.stage=el('planStage').value;
  if(el('planClose'))p.targetClose=el('planClose').value;
  if(el('planGoal'))p.goal=el('planGoal').value;
  if(el('planMax'))p.maxAuthorization=Math.max(0,Number(el('planMax').value)||0);
  if(el('planDate')&&!el('planDate').disabled)p.preferredDate=el('planDate').value;
  if(el('planWindow')&&!el('planWindow').disabled)p.preferredWindow=el('planWindow').value;
  if(el('planAccess')&&!el('planAccess').disabled)p.accessNotes=el('planAccess').value.trim();
}
function planCanLeave(p,target){
  if(target<=p.step)return true;
  if(!p.clientName||!p.address){toast(t('Write the client and the property address first.','Primero escribe el cliente y la dirección de la propiedad.'));return false}
  if(p.clientEmail&&!validEmail(p.clientEmail)){toast(I18N.badEmail[state.lang==='en'?0:1]);return false}
  if(target>3&&!p.items.length){toast(t('Select at least one repair.','Selecciona al menos una reparación.'));return false}
  return true;
}
async function planGo(target){
  const p=currentPlan();planReadForm(p);
  if(!planCanLeave(p,target))return;
  p.step=Math.min(8,Math.max(1,target));
  render();window.scrollTo({top:0,behavior:'smooth'});
  if(await savePlan()&&state.route==='repairplan'&&!userIsEditing())render();
}
function bindPlan(){
  if(state.route!=='repairplan')return;
  const p=currentPlan();
  document.querySelectorAll('[data-plan-step]').forEach(b=>b.onclick=()=>planGo(Number(b.dataset.planStep)));
  document.querySelectorAll('[data-plan-next]').forEach(b=>b.onclick=()=>planGo(p.step+1));
  document.querySelectorAll('[data-plan-prev]').forEach(b=>b.onclick=()=>planGo(p.step-1));
  if(el('planNew'))el('planNew').onclick=()=>{if(p.items.length&&!p.id&&!confirm(t('Start a new plan? The current draft has not been saved.','¿Empezar un plan nuevo? El borrador actual no se ha guardado.')))return;state.plan=newPlan();state.planQuery='';keepPlanDraft();render()};
  if(el('planPicker'))el('planPicker').onchange=e=>{const row=(state.plans||[]).find(x=>String(x.id)===e.target.value);if(!row)return;state.plan=JSON.parse(JSON.stringify(row));keepPlanDraft();render()};
  if(el('planClient'))el('planClient').onchange=()=>{const c=clientRows().find(x=>x.name===el('planClient').value.trim());if(!c)return;if(el('planClientEmail')&&!el('planClientEmail').value)el('planClientEmail').value=c.email||'';if(el('planAddress')&&!el('planAddress').value)el('planAddress').value=c.address||''};
  ['planClient','planClientEmail','planAddress','planStage','planClose','planGoal','planDate','planWindow','planAccess'].forEach(id=>{const n=el(id);if(n)n.addEventListener('change',()=>{planReadForm(p);keepPlanDraft()})});
  if(el('planClose'))el('planClose').min=todayLocal();
  document.querySelectorAll('[data-plan-pick]').forEach(input=>input.onchange=()=>{
    const id=input.dataset.planPick;
    if(input.checked){const row=state.estimate.find(x=>x.id===id)||state.catalog.find(x=>x.id===id);if(row&&!p.items.some(x=>x.id===id))p.items.push(planItemFrom(row))}
    else p.items=p.items.filter(x=>x.id!==id);
    p.maxAuthorization=0;keepPlanDraft();render();
  });
  const search=el('planSearch');
  if(search){
    const paint=()=>{state.planQuery=search.value;el('planAddResults').innerHTML=planSearchHtml();bindPlanAdd()};
    search.oninput=paint;
    bindPlanAdd();
  }
  document.querySelectorAll('[data-plan-qty]').forEach(input=>input.onchange=()=>{const row=p.items.find(x=>x.id===input.dataset.planQty);if(!row)return;row.qty=Math.min(10000,Math.max(1,Math.round(Number(input.value)||1)));p.maxAuthorization=0;keepPlanDraft();render()});
  document.querySelectorAll('[data-plan-pricing]').forEach(b=>b.onclick=()=>{p.pricing=b.dataset.planPricing;p.maxAuthorization=0;keepPlanDraft();render()});
  if(el('planMax'))el('planMax').onchange=()=>{p.maxAuthorization=Math.max(0,Number(el('planMax').value)||0);keepPlanDraft()};
  document.querySelectorAll('[data-plan-credit]').forEach(input=>input.onchange=()=>{p.credit=Number(input.dataset.planCredit)||0;keepPlanDraft();render()});
  if(el('planSendApproval'))el('planSendApproval').onclick=async()=>{
    if(!validEmail(p.clientEmail)){toast(t('Add the client email in the Property step.','Agrega el correo del cliente en el paso Propiedad.'));return}
    const button=el('planSendApproval');button.disabled=true;
    const subject=`${t('Repair plan for your approval','Plan de reparaciones para tu aprobación')} · ${p.address}`;
    const body=planSummaryText(p);
    const result=await sendCompanyEmail(p.clientEmail,subject,body);
    if(result!=='sent')openMailDraft(p.clientEmail,subject,body);
    if(p.status==='Draft')p.status='Approval sent';
    await savePlan(true);render();
    toast(result==='sent'?t(`Plan emailed to ${p.clientEmail} from the SAFE company email.`,`Plan enviado a ${p.clientEmail} desde el correo de SAFE.`):t('Your email app opened with the plan ready to send.','Se abrió tu correo con el plan listo para enviar.'));
  };
  if(el('planApproved'))el('planApproved').onclick=async()=>{p.status='Approved';await savePlan(true);render();toast(t('Approval recorded. Next: schedule with Management.','Aprobación registrada. Siguiente: agenda con Management.'))};
  if(el('planDispatch'))el('planDispatch').onclick=async()=>{
    planReadForm(p);
    if(p.status!=='Approved'){toast(t('Record the client approval first (Approval step).','Primero registra la aprobación del cliente (paso Aprobación).'));return}
    if(!p.preferredDate){toast(t('Choose the preferred date.','Elige la fecha preferida.'));return}
    if(p.preferredDate<todayLocal()){toast(t('Choose today or a future date.','Elige hoy o una fecha futura.'));return}
    const button=el('planDispatch');button.disabled=true;button.innerHTML=`<span class="btn-spin" aria-hidden="true"></span>${t('Sending…','Enviando…')}`;
    const r=planRollup(p);
    const notes=`${planSummaryText(p)}\n\n${t('Preferred date','Fecha preferida')}: ${p.preferredDate} · ${pairLabel(PLAN_WINDOWS,p.preferredWindow)}\n${t('Property access','Acceso a la propiedad')}: ${p.accessNotes||'—'}`;
    try{
      const req=await SafeApi.post('/api/safe/requests',{address:p.address,client:p.clientName,contact:state.account?.name||'Realtor',notes,type:'Repair plan',sourceApp:'Ecosystem',source:'Realtor Portal',items:p.items.length,value:Number(p.maxAuthorization)||planMaxDefault(p,r),dueAt:p.preferredDate});
      p.requestId=req?.id||'';p.status='Sent to Management';p.step=8;
      const saved=await savePlan(true);
      await refreshHub(true);
      toast(saved?t(`Plan sent to Management (${p.requestId}).`,`Plan enviado a Management (${p.requestId}).`):t(`Sent to Management (${p.requestId}), but the plan could not be saved.`,`Enviado a Management (${p.requestId}), pero el plan no se pudo guardar.`));
    }catch{
      button.disabled=false;button.textContent=t('Send to Management','Enviar a Management');
      toast(t('Management could not receive it. Check the connection and try again.','Management no lo pudo recibir. Revisa la conexión e intenta de nuevo.'));
    }
  };
}
function bindPlanAdd(){
  document.querySelectorAll('[data-plan-add]').forEach(b=>b.onclick=()=>{const p=currentPlan();const row=state.catalog.find(x=>x.id===b.dataset.planAdd);if(!row||p.items.some(x=>x.id===row.id))return;p.items.push(planItemFrom(row));p.maxAuthorization=0;keepPlanDraft();render();toast(t('Repair added to the plan','Reparación agregada al plan'))});
}

function quoteSignature(){return JSON.stringify([state.repairOption,Number(state.transportAmount)||0,state.estimate.map(r=>[r.id,Number(r.low)||0,Number(r.high)||0])])}
function quoteAlreadySent(){const key=estimateKey();return !!key&&state.estimate.length>0&&localStorage.getItem(key+':sent')===quoteSignature()}
function estimatesView(){
  const lines=state.estimate.length?state.estimate.map(negotiateLine).join('')+transportLine()+`<p class="policy price-help">${t('The low price is the standard scope. The high price is the same service when the review condition applies. Transportation is an extra charge and is not inside either price. Edit the numbers, then negotiate them with Management.','El precio bajo es el alcance estándar. El precio alto es el mismo servicio cuando aplica la condición de revisión. El transporte es un cargo aparte y no va dentro de ninguno de los dos. Edita los números y negócialos con Management.')}</p>`:`<div class="policy">${t('Search the catalog and add repairs to build an estimate.','Busca en el catálogo y agrega reparaciones para armar el estimado.')}</div>`;
  return `${pageHead('REPAIR NEGOTIATION','Give your buyer or seller clear options','Dale opciones claras a tu comprador o vendedor','Compare priority repairs, the recommended grouped scope and the complete property plan before making a repair request or discussing a credit.','Compara reparaciones prioritarias, el alcance recomendado y el plan completo antes de pedir reparaciones o hablar de un crédito.',`<button class="button secondary" data-route="search">+ ${t('Add repair items','Agregar reparaciones')}</button><button class="button secondary" data-action="negotiate">${t('Negotiate prices','Negociar precios')}</button>${quoteAlreadySent()?`<span class="tag green quote-sent">✓ ${t('Quote sent to the client','Cotización enviada al cliente')}</span>`:`<button class="button primary" data-action="generate-quote">${t('Generate and send','Generar y enviar')}</button>`}`)}
  <div class="estimate-builder">
    <section class="card"><div class="card-head"><div><span class="eyebrow">${t('SELECTED SCOPE','ALCANCE SELECCIONADO')}</span><h2>${t('Repair items','Reparaciones')}</h2></div><span class="card-head-actions"><span class="tag aqua">${state.estimate.length} ${t('items','ítems')}</span>${state.estimate.length?`<button type="button" class="text-button danger" data-clear-estimate>${t('Remove all','Quitar todas')}</button>`:''}</span></div><div class="estimate-lines">${lines}</div></section>
    <section class="grid">${[
      ['minimum',t('OPTION 1','OPCIÓN 1'),t('Minimum required repairs','Reparaciones mínimas'),t('Safety and transaction-critical findings.','Seguridad y hallazgos críticos.'),false],
      ['recommended',t('OPTION 2','OPCIÓN 2'),t('Recommended repair plan','Plan recomendado'),t('Priority work grouped for a more efficient crew visit.','Trabajo prioritario agrupado para eficiencia.'),true],
      ['complete',t('OPTION 3','OPCIÓN 3'),t('Complete property improvement','Mejora completa'),t('Repair plan plus selected upgrades.','Reparaciones más mejoras seleccionadas.'),false]
    ].map(([key,eyebrow,title,body,suggested])=>`<label class="option-card${suggested?' recommended':''}${state.repairOption===key?' selected':''}"><span class="option-head"><input type="radio" name="repairOption" value="${key}" ${state.repairOption===key?'checked':''}><span class="eyebrow">${eyebrow}</span>${suggested?`<span class="tag green recommend">${t('RECOMMENDED','RECOMENDADO')}</span>`:''}</span><h3>${title}</h3><p>${body}</p><div class="option-price" data-option-price="${key}">${optionMoney(key)}</div><span class="option-pick">${state.repairOption===key?t('Selected','Seleccionada'):t('Select this price','Seleccionar este precio')}</span></label>`).join('')}</section>
  </div>`;
}

function localClients(){try{return JSON.parse(localStorage.getItem('safe-realtor-clients')||'[]')}catch{return[]}}
const clientKeyOf=c=>String(c?.email||c?.name||'').trim().toLowerCase();
function clientProfile(c){const keys=[String(c?.email||'').trim().toLowerCase(),String(c?.name||'').trim().toLowerCase()].filter(Boolean);return (state.clientProfiles||[]).find(p=>keys.includes(p.key)||keys.includes(String(p.name||'').trim().toLowerCase()))||null}
function clientRows(){
  const live=liveContacts().filter(c=>String(c.role||'')==='Client');
  const extra=localClients().filter(c=>!live.some(x=>String(x.name||'').toLowerCase()===String(c.name||'').toLowerCase()));
  const rows=[...extra,...live];
  (state.clientProfiles||[]).forEach(p=>{if(!rows.some(c=>clientProfile(c)===p))rows.push({name:p.name,email:p.email,phone:p.phone,address:p.address,role:'Client',id:'profile-'+p.key})});
  return rows.map(c=>{const p=clientProfile(c);return p?{...c,name:p.name||c.name,email:p.email||c.email,phone:p.phone||c.phone,address:p.address||c.address,profile:p}:c});
}
async function loadClientProfiles(){
  if(!state.account?.email)return;
  try{const r=await fetch(`/api/realtor/client-profiles?realtor=${encodeURIComponent(state.account.email)}`);if(r.ok){const rows=await r.json();if(Array.isArray(rows)){state.clientProfiles=rows;if(state.route==='clients')render()}}}catch{}
}
const CLIENT_SIDES=[['','—','—'],['Buyer','Buyer','Comprador'],['Seller','Seller','Vendedor'],['Both','Buyer and seller','Comprador y vendedor']];
const CLIENT_CHANNELS=[['','—','—'],['Gmail','Email','Correo'],['SMS','Text message','Mensaje de texto'],['WhatsApp','WhatsApp','WhatsApp'],['Call','Phone call','Llamada']];
function nextYearly(dateText){
  if(!/^\d{4}-\d{2}-\d{2}$/.test(dateText||''))return null;
  const [,m,d]=dateText.split('-').map(Number),today=new Date();today.setHours(0,0,0,0);
  let next=new Date(today.getFullYear(),m-1,d);if(next<today)next=new Date(today.getFullYear()+1,m-1,d);
  return {date:next,days:Math.round((next-today)/86400000)};
}
function clientKeyDate(p){
  if(!p)return null;
  const closed=/^\d{4}-\d{2}-\d{2}$/.test(p.closingDate||'')&&new Date(p.closingDate+'T00:00')<=new Date();
  const list=[[nextYearly(p.birthday),t('Birthday','Cumpleaños')],[closed?nextYearly(p.closingDate):null,t('Home anniversary','Aniversario de compra')]].filter(x=>x[0]);
  if(!closed&&p.closingDate){const d=new Date(p.closingDate+'T00:00'),today=new Date();today.setHours(0,0,0,0);list.push([{date:d,days:Math.round((d-today)/86400000)},t('Closing','Cierre')])}
  list.sort((a,b)=>a[0].days-b[0].days);
  if(!list.length)return null;
  const [{date,days},label]=list[0];
  return `${label} · ${date.toLocaleDateString(state.lang==='en'?'en-US':'es-US',{month:'short',day:'numeric'})}${days===0?` · ${t('today','hoy')}`:days>0?` · ${t(`in ${days} days`,`en ${days} días`)}`:''}`;
}
function openClientModal(client=null){
  let modal=el('clientModal');
  if(!modal){
    modal=document.createElement('div');
    modal.className='modal';
    modal.id='clientModal';
    document.body.appendChild(modal);
    modal.addEventListener('click',e=>{if(e.target===modal&&modal.dataset.saving!=='1')modal.classList.remove('open')});
  }
  const p=client?(clientProfile(client)||{}):{},v=k=>esc(p[k]??client?.[k]??'');
  const opts=(list,value)=>list.map(o=>`<option value="${esc(o[0])}"${o[0]===(value||'')?' selected':''}>${esc(t(o[1],o[2]))}</option>`).join('');
  const editing=!!client;
  modal.innerHTML=`<form class="modal-card client-form" id="clientForm" novalidate><div class="modal-head"><div><span class="eyebrow">${t('CLIENT PROFILE','FICHA DEL CLIENTE')}</span><h2>${editing?t('Edit client','Editar cliente'):t('Add client','Agregar cliente')}</h2></div><button type="button" class="close" data-close-client aria-label="${t('Close','Cerrar')}" data-aria-en="Close" data-aria-es="Cerrar">×</button></div>
  <h3 class="form-section">${t('Contact','Contacto')}</h3><div class="form-grid"><label><span>${t('Client name','Nombre del cliente')} *</span><input id="newClientName" autocomplete="name" maxlength="160" required value="${v('name')}"></label><label><span>${t('Property address','Dirección de la propiedad')}</span><input id="newClientAddress" autocomplete="street-address" maxlength="250" value="${v('address')}"></label><label><span>Email</span><input id="newClientEmail" type="email" placeholder="${t('name@email.com','nombre@correo.com')}" autocomplete="email" maxlength="160" value="${v('email')}"></label><label><span>${t('Phone','Teléfono')}</span><input id="newClientPhone" ${PHONE_ATTRS} value="${v('phone')}"></label></div>
  <h3 class="form-section">${t('Transaction','Transacción')}</h3><div class="form-grid"><label><span>${t('The client is','El cliente es')}</span><select id="newClientSide">${opts(CLIENT_SIDES,p.side)}</select></label><label><span>${t('Closing date','Fecha de cierre')}</span><input id="newClientClosing" type="date" value="${esc(p.closingDate||'')}"></label></div>
  <h3 class="form-section">${t('Relationship and loyalty','Relación y fidelización')}</h3><div class="form-grid"><label><span>${t('Birthday','Cumpleaños')}</span><input id="newClientBirthday" type="date" max="${todayLocal()}" value="${esc(p.birthday||'')}"></label><label><span>${t('Preferred contact','Medio de contacto preferido')}</span><select id="newClientChannel">${opts(CLIENT_CHANNELS,p.preferredChannel)}</select></label><label class="full"><span>${t('Family and pets','Familia y mascotas')}</span><input id="newClientHousehold" maxlength="400" placeholder="${t('Spouse Ana, two kids, dog named Max','Esposa Ana, dos hijos, perro llamado Max')}" value="${esc(p.household||'')}"></label><label class="full"><span>${t('Interests and home plans','Intereses y planes para la casa')}</span><input id="newClientInterests" maxlength="400" placeholder="${t('Gardening, wants to remodel the kitchen next year','Jardinería, quiere remodelar la cocina el próximo año')}" value="${esc(p.interests||'')}"></label><label class="full"><span>${t('Notes','Notas')}</span><textarea id="newClientNotes" rows="2" maxlength="2000">${esc(p.notes||'')}</textarea></label></div>
  <label class="consent-row"><input type="checkbox" id="newClientConsent" ${p.consent?'checked':''}> <span>${t('The client agrees to receive tips, reminders and greetings from me.','El cliente acepta recibir consejos, recordatorios y saludos de mi parte.')}</span></label>
  <div class="form-warning" id="clientFormError" hidden></div>
  <div class="modal-actions"><button type="button" class="button secondary" data-close-client>${t('Cancel','Cancelar')}</button><button class="button primary" type="submit" id="saveClientBtn">${editing?t('Save changes','Guardar cambios'):t('Add client','Agregar cliente')}</button></div><div class="client-saving" hidden><span class="client-spin" aria-hidden="true"></span><strong>${t('Saving the client…','Guardando el cliente…')}</strong></div></form>`;
  modal.querySelectorAll('[data-close-client]').forEach(b=>b.onclick=()=>{if(modal.dataset.saving==='1')return;modal.classList.remove('open')});
  modal.querySelectorAll('[data-phone]').forEach(i=>i.addEventListener('input',()=>{i.value=i.value.replace(/\D/g,'').slice(0,10)}));
  modal.querySelector('form').onsubmit=async e=>{
    e.preventDefault();
    if(modal.dataset.saving==='1')return;
    const err=el('clientFormError'),fail=(msg,id)=>{err.textContent='⚠ '+msg;err.hidden=false;if(id)el(id).focus()};
    err.hidden=true;
    const name=el('newClientName').value.trim(),address=el('newClientAddress').value.trim(),email=el('newClientEmail').value.trim(),phone=el('newClientPhone').value.trim();
    const birthday=el('newClientBirthday').value,closingDate=el('newClientClosing').value;
    if(!name)return fail(t('Write the client name.','Escribe el nombre del cliente.'),'newClientName');
    if(email&&!validEmail(email))return fail(I18N.badEmail[state.lang==='en'?0:1],'newClientEmail');
    if(!validPhone(phone))return fail(PHONE_ERROR(),'newClientPhone');
    if(birthday&&birthday>todayLocal())return fail(t('The birthday cannot be in the future.','El cumpleaños no puede ser una fecha futura.'),'newClientBirthday');
    const busy=modal.querySelector('.client-saving'),submit=el('saveClientBtn');
    modal.dataset.saving='1';modal.setAttribute('aria-busy','true');if(busy)busy.hidden=false;
    modal.querySelectorAll('input,button,select,textarea').forEach(n=>{n.disabled=true});
    if(submit)submit.innerHTML=`<span class="btn-spin" aria-hidden="true"></span>${t('Saving…','Guardando…')}`;
    const record={name,address,email,phone,role:'Client',id:client?.id||'local-'+Date.now()};
    const list=localClients().filter(c=>String(c.name||'').toLowerCase()!==name.toLowerCase()&&(!client||String(c.name||'').toLowerCase()!==String(client.name||'').toLowerCase()));
    list.unshift(record);
    localStorage.setItem('safe-realtor-clients',JSON.stringify(list));
    const profile={realtorEmail:state.account?.email||'',key:client?(p.key||clientKeyOf(client)):'',name,email,phone,address,side:el('newClientSide').value,closingDate:closingDate||null,birthday:birthday||null,preferredChannel:el('newClientChannel').value,household:el('newClientHousehold').value.trim(),interests:el('newClientInterests').value.trim(),notes:el('newClientNotes').value.trim(),consent:el('newClientConsent').checked};
    let savedOnServer=false,error='';
    try{
      const post=(url,body)=>{const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),8000);return fetch(url,{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify(body),signal:ctrl.signal}).finally(()=>clearTimeout(timer))};
      const res=await post('/api/realtor/client-profiles',profile);
      const body=await res.json().catch(()=>({}));
      if(res.ok){savedOnServer=true;state.clientProfiles=[body,...(state.clientProfiles||[]).filter(x=>x.key!==body.key&&x.key!==profile.key)]}
      else if(res.status===400)error=(state.lang==='es'&&body.errorEs)||body.error||'';
      if(!editing&&!error){const r=await post('/api/safe/clients',record).catch(()=>null);if(r?.ok&&window.refreshHub)refreshHub(true).catch(()=>{})}
    }catch{}
    modal.dataset.saving='';modal.removeAttribute('aria-busy');if(busy)busy.hidden=true;
    modal.querySelectorAll('input,button,select,textarea').forEach(n=>{n.disabled=false});
    if(submit)submit.textContent=editing?t('Save changes','Guardar cambios'):t('Add client','Agregar cliente');
    if(error)return fail(error);
    modal.classList.remove('open');
    render();
    toast(savedOnServer?t('Client saved','Cliente guardado'):t('Client saved on this device; the database could not save it.','Cliente guardado en este equipo; la base de datos no lo pudo guardar.'));
  };
  modal.classList.add('open');
  setTimeout(()=>el('newClientName')?.focus(),30);
}
function clientsView(){const rows=clientRows();const props=state.hub?.properties||[];const body=rows.length?rows.map((c,i)=>{const p=props.find(x=>x.clientId===c.id);const job=jobs().find(j=>j.client===c.name);const pr=c.profile,sideRow=pr?.side?CLIENT_SIDES.find(x=>x[0]===pr.side):null,side=sideRow?t(sideRow[1],sideRow[2]):'';const key=clientKeyDate(pr);return `<tr><td><div class="person"><span class="avatar">${initials(c.name)}</span><span><strong>${esc(c.name)}</strong><small style="display:block">${esc([side,c.email||c.phone].filter(Boolean).join(' · '))}</small></span></div></td><td>${esc(c.address||p?.address||job?.address||'—')}</td><td><span class="tag aqua">${esc(woStatusLabel(job?.status||p?.status||'Active'))}</span></td><td>${key?esc(key):job?.checkInAt?t('Worker on site','Trabajador en sitio'):pr?t('Follow the job','Seguir el trabajo'):`<span class="muted-note">${t('Complete the profile to get reminders','Completa la ficha para recibir recordatorios')}</span>`}</td><td class="price">${job?.value?money(job.value):'—'}</td><td><button class="button secondary small" type="button" data-edit-client="${i}">${pr?t('Edit profile','Editar ficha'):t('Complete profile','Completar ficha')}</button></td></tr>`}).join(''):`<tr><td colspan="6">${t('No clients yet. Add one with the button above.','Aún no hay clientes. Agrega uno con el botón de arriba.')}</td></tr>`;return `${pageHead('RELATIONSHIPS','Every client and property in one place','Cada cliente y propiedad en un lugar','The inspection, estimate, SAFE request, project status and follow-up stay connected.','La inspección, estimado, solicitud, trabajo y seguimiento quedan conectados.',`<button class="button primary" id="addRealtorClient">+ ${t('Add client','Agregar cliente')}</button>`)}<section class="card table-wrap"><table class="table"><thead><tr><th>${t('Client','Cliente')}</th><th>${t('Property','Propiedad')}</th><th>${t('Stage','Etapa')}</th><th>${t('Next follow-up','Próximo seguimiento')}</th><th>${t('Value','Valor')}</th><th></th></tr></thead><tbody>${body}</tbody></table></section>`}
const clientChannels=[{id:'whatsapp',en:'WhatsApp',es:'WhatsApp',needs:'phone'},{id:'gmail',en:'Gmail',es:'Gmail',needs:'email'},{id:'sms',en:'SMS',es:'SMS',needs:'phone'},{id:'facebook',en:'Facebook',es:'Facebook',needs:'name'},{id:'instagram',en:'Instagram',es:'Instagram',needs:'name'}];
function channelLabel(id){if(id==='job')return t('SAFE Job Thread','Hilo de trabajo SAFE');const row=clientChannels.find(c=>c.id===id);return row?t(row.en,row.es):id}
function channelDestination(client,channel){const spec=clientChannels.find(c=>c.id===channel);if(!client||!spec)return '';if(spec.needs==='phone')return client.phone||'';if(spec.needs==='email')return client.email||'';return client.name||''}
function messagesView(){
  const tabs=[{id:'job',en:'SAFE Job Thread',es:'Hilo de trabajo SAFE'},...clientChannels].map(c=>`<button type="button" class="chip ${state.messageChannel===c.id?'active':''}" data-message-channel="${c.id}">${t(c.en,c.es)}</button>`).join('');
  return `${pageHead('SHARED COMMUNICATIONS','Know when the worker arrives and answer from one thread','Sabe cuándo llega el trabajador y responde en una conversación','The assigned Realtor, worker and SAFE Management share the job thread. Client channels keep their own conversations.','El Realtor asignado, trabajador y Management comparten la conversación del trabajo. Cada canal del cliente guarda su propia conversación.')}<div class="channel-tabs">${tabs}</div>${state.messageChannel==='job'?jobInbox():clientInbox()}`;
}
function workerLabel(j){return !j?.worker||j.worker==='Unassigned'?t('No worker yet','Sin trabajador'):j.worker}
const SYSTEM_MESSAGES=[
  ['The assigned Realtor will receive arrival and access requests here.','El Realtor asignado recibirá aquí la llegada y las solicitudes de acceso.'],
  ['I arrived at the property. Please send the access instructions.','Llegué a la propiedad. Por favor envíen las instrucciones de acceso.'],
  ['Secure access instruction sent. Value masked and worker notified.','Instrucción de acceso segura enviada. Valor oculto y trabajador notificado.'],
  ['Secure access instruction sent · value hidden','Instrucción segura enviada · valor oculto'],
  ['Arrival acknowledged. Management is monitoring the shared thread.','Llegada confirmada. Management supervisa la conversación.']
];
function messageText(body){const pair=SYSTEM_MESSAGES.find(p=>p[0]===body||p[1]===body);return pair?t(pair[0],pair[1]):body}
function activeJob(){const live=jobs();return live.find(j=>j.id===state.jobId)||live.find(j=>j.workerId)||live[0]}
function jobThreadMessages(job){const thread=(state.hub?.threads||[]).find(x=>x.publicId===job?.threadId);return thread?jobMessages().filter(m=>m.threadId===thread.id):[]}
function apiError(e,fallback){try{const b=JSON.parse(e.message);return (state.lang==='es'&&b.errorEs)||b.error||fallback}catch{return fallback}}
function jobInbox(){
  const live=jobs();const job=activeJob();const list=jobThreadMessages(job);
  const threads=live.length?live.map(j=>`<button type="button" class="thread ${j===job?'active':''}" data-job="${esc(j.id)}"><strong>${esc(j.id)} <small>${esc(woStatusLabel(j.status))}</small></strong><p>${esc(j.address)} · ${esc(workerLabel(j))}</p></button>`).join(''):`<div class="thread active"><strong>${t('No jobs yet','Aún no hay trabajos')}</strong><p>${t('Send a SAFE request first.','Primero envía una solicitud SAFE.')}</p></div>`;
  const bubbles=list.length?list.map(m=>`<div class="bubble ${m.senderRole==='Realtor'?'me':''}"><b>${esc(m.senderName)}</b><br>${esc(messageText(m.body))}</div>`).join(''):`<div class="bubble"><b>Management</b><br>${job?t('No messages for this job yet.','Aún no hay mensajes de este trabajo.'):t('This thread fills when a job exists in IndorDB.','Esta conversación se llena cuando hay un trabajo en IndorDB.')}</div>`;
  return `<section class="card inbox"><div class="threads">${threads}</div><div class="conversation"><div class="conversation-head"><div><strong>${esc(job?.address||t('No active job yet','Aún no hay trabajo'))}</strong><br><small>${esc(job?.requestId||'')} · ${esc(job?.id||'')} · ${esc(job?workerLabel(job):'')}</small></div><span class="tag green">${esc(woStatusLabel(job?.status))}</span></div><div class="messages" id="jobMessages">${bubbles}</div><div class="detail-block" style="margin:12px"><strong>${t('Secure property access','Acceso seguro a la propiedad')}</strong><p>${t('Only the assigned worker and Management can view the instruction. The value is masked after it is sent.','Solo el trabajador asignado y Management pueden ver la instrucción. El valor se oculta después de enviarlo.')}</p>${job?.workerId?`<div class="composer" style="padding:0;border:0"><input id="accessCode" type="password" maxlength="500" autocomplete="off" placeholder="${t('Lockbox code or access instruction','Código de lockbox o instrucción')}"><button class="button navy" id="sendAccessCode">${t('Send securely','Enviar seguro')}</button></div>`:`<p><small>${t('Available when Management assigns a worker to this job.','Disponible cuando Management asigne un trabajador a este trabajo.')}</small></p>`}</div><div class="composer"><input id="messageInput" placeholder="${t('Write to worker and Management…','Escribir al trabajador y Management…')}"><button class="button primary" id="sendMessage">${t('Send','Enviar')}</button></div></div></section>`;
}
function clientInbox(){
  const channel=state.messageChannel;
  const people=clientRows();
  const active=people.find(c=>serviceKey(c)===state.messageClient)||people[0];
  if(active)state.messageClient=serviceKey(active);
  const threads=people.length?people.map(c=>{const key=serviceKey(c);const last=(state.channelMessages||[]).filter(m=>m.channel===channel&&m.clientKey===key).at(-1);return `<button type="button" class="thread ${key===state.messageClient?'active':''}" data-message-client="${esc(key)}"><strong>${esc(c.name)}</strong><p>${esc(last?.body||channelDestination(c,channel)||t('No messages yet','Aún no hay mensajes'))}</p></button>`}).join(''):`<div class="thread active"><strong>${t('No clients yet','Aún no hay clientes')}</strong><p>${t('Add a client before sending.','Agrega un cliente antes de enviar.')}</p></div>`;
  const dest=channelDestination(active,channel);
  const spec=clientChannels.find(c=>c.id===channel);
  const missing=active&&spec?.needs==='phone'&&!active.phone?t('Add this client’s phone to send by this channel.','Agrega el teléfono de este cliente para enviar por este canal.'):active&&spec?.needs==='email'&&!validEmail(active.email||'')?t('Add this client’s email to send by Gmail.','Agrega el correo de este cliente para enviar por Gmail.'):'';
  const link=connectionFor(channel);
  if(!link)return `<section class="card connect-needed"><div><span class="eyebrow">${esc(channelLabel(channel))}</span><h2>${t(`Connect ${channelLabel(channel)} first`,`Primero conecta ${channelLabel(channel)}`)}</h2><p>${t('Authorize the account you use for this channel. Then your client conversations appear here.','Autoriza la cuenta que usas en este canal. Después tus conversaciones con clientes aparecen aquí.')}</p></div><button class="button primary" type="button" data-connect="${channel}">${t('Connect now','Conectar ahora')}</button></section>`;
  const bubbles=(state.channelMessages||[]).filter(m=>m.channel===channel&&m.clientKey===state.messageClient).map(m=>`<div class="bubble me"><b>${esc(state.account?.name||'Realtor')}</b><br>${esc(m.body)}</div>`).join('')||`<div class="bubble"><b>${esc(channelLabel(channel))}</b><br>${active?t('Write the first message. It is saved in the database.','Escribe el primer mensaje. Queda guardado en la base de datos.'):t('Add a client first.','Primero agrega un cliente.')}</div>`;
  return `<section class="card inbox"><div class="threads">${threads}</div><div class="conversation"><div class="conversation-head"><div><strong>${esc(active?.name||t('Choose a client','Elige un cliente'))}</strong><br><small>${esc(channelLabel(channel))}${dest?` · ${esc(dest)}`:''}</small></div><small>${t('From','Desde')} ${esc(link.account)}</small></div><div class="messages" id="channelMessages">${bubbles}</div>${missing?`<p class="audience-note" style="padding:0 14px">${missing}</p>`:''}<div class="composer"><input id="channelMessageInput" placeholder="${t('Write to the client…','Escribir al cliente…')}" ${active?'':'disabled'}><button class="button primary" id="sendChannelMessage" type="button" ${active?'':'disabled'}>${t('Send','Enviar')}</button></div></div></section>`;
}

function followupsView(){
  const visits=loadVisits().map(v=>({...v,bucket:visitBucket(v)}));
  const jobsToday=jobs().map(j=>({kind:'job',title:j.client||j.address,detail:`${woStatusLabel(j.status)} · ${workerLabel(j)}`,when:j.checkInAt?t('Worker on site','Trabajador en sitio'):t('Track this job','Seguir este trabajo'),bucket:j.checkInAt?'today':'next'}));
  const cards=[...visits.map(v=>({kind:'visit',...v,title:v.client,detail:v.address||v.note||'',when:visitWhen(v)})),...jobsToday];
  const column=(key,title)=>`<div class="followup-column"><h3>${title}<span>${cards.filter(c=>c.bucket===key).length}</span></h3>${cards.filter(c=>c.bucket===key).map(c=>c.kind==='visit'?`<article class="followup-card"><strong>${esc(c.title)}</strong><p>${esc(c.detail)}</p><div class="row"><small>${esc(c.when)}</small><span><button type="button" data-edit-visit="${esc(c.id)}">${t('Edit','Editar')}</button>${c.bucket==='done'?'':`<button type="button" data-complete-visit="${esc(c.id)}" aria-label="${t('Mark done','Marcar hecha')}">✓</button>`}</span></div></article>`:`<article class="followup-card"><strong>${esc(c.title)}</strong><p>${esc(c.detail)}</p><div class="row"><small>${esc(c.when)}</small></div></article>`).join('')||`<p>${t('Nothing scheduled yet.','Nada programado todavía.')}</p>`}</div>`;
  return `${pageHead('FOLLOW-UP PLAYBOOK','Know exactly who needs attention','Sabe exactamente quién necesita atención','Schedule and edit your client visits. Today, upcoming and completed stay on this agenda.','Programa y edita tus visitas con clientes. Hoy, próximas y completadas quedan en esta agenda.',`<button class="button secondary" data-route="schedule">${t('View calendar','Ver agenda')}</button><button class="button primary" id="addVisit" type="button">+ ${t('Schedule visit','Programar visita')}</button>`)}<div class="followup-grid">${column('today',t('Due today','Para hoy'))}${column('next',t('Coming next','Próximos'))}${column('done',t('Completed','Completados'))}</div>`;
}
function clientServiceKey(){return `safe-realtor-client-services:${(state.account?.email||'local').toLowerCase()}`}
function loadClientServices(){try{return JSON.parse(localStorage.getItem(clientServiceKey())||'[]')}catch{return[]}}
function saveClientServices(list){localStorage.setItem(clientServiceKey(),JSON.stringify(list))}
function serviceKey(person){return String(person?.email||person?.name||'').trim().toLowerCase()}
function selectedServices(){return state.estimate.map(r=>({id:String(r.id||''),service:r.service||'',category:r.category||''})).filter(s=>s.category||s.service)}
function rememberClientWork(person,services){
  services=(services||[]).filter(s=>s&&(s.category||s.service)).map(s=>({id:String(s.id||''),service:s.service||'',category:s.category||''}));
  if(!person?.name||!services.length)return;
  const list=loadClientServices();
  const key=serviceKey(person);
  const prev=list.find(x=>serviceKey(x)===key);
  const next={name:person.name,email:person.email||prev?.email||'',phone:person.phone||prev?.phone||'',address:person.address||prev?.address||'',services,updatedAt:new Date().toISOString()};
  const same=prev&&JSON.stringify(prev.services)===JSON.stringify(services)&& (prev.address||'')===next.address;
  if(prev)Object.assign(prev,next);else list.unshift(next);
  saveClientServices(list);
  if(same)return;
  fetch('/api/realtor/client-services',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({realtorEmail:state.account?.email||'',...next}),keepalive:true}).catch(()=>{});
}
function absorbChosenServices(){
  try{
    const budget=JSON.parse(localStorage.getItem('safe-realtor-budget')||'null');
    if(budget?.client&&Array.isArray(budget.items)){
      const services=budget.items.map(id=>state.catalog.find(r=>r.id===id)).filter(Boolean);
      rememberClientWork({name:budget.client,email:budget.email||'',address:budget.address||''},services);
    }
  }catch{}
  (state.hub?.requests||[]).forEach(req=>{
    const notes=normalized(req.notes||'');
    if(!req.client||notes.length<8)return;
    const services=state.catalog.filter(r=>r.service&&notes.includes(normalized(r.service))).slice(0,20);
    rememberClientWork({name:req.client,email:'',address:req.address||''},services);
  });
}
function clientsForTip(template){
  const topics=new Set(template?.topics||[]);
  const people=loadClientServices().map(p=>({...p,services:p.services||[]}));
  const known=new Set(people.map(serviceKey));
  clientRows().forEach(c=>{
    const row={name:c.name,email:c.email||'',phone:c.phone||'',address:c.address||'',services:[]};
    if(row.name&&!known.has(serviceKey(row)))people.push(row);
  });
  return people.map(p=>{
    const hit=(p.services||[]).filter(s=>topics.has(s.category));
    return {...p,hit,match:topics.size>0&&hit.length>0};
  }).sort((a,b)=>Number(b.match)-Number(a.match)||String(a.name).localeCompare(String(b.name)));
}
function topicNames(template){return (template?.topics||[]).map(c=>state.lang==='en'?c:(categoryES[c]||c))}
function audienceHtml(template){
  const rows=clientsForTip(template);
  const matches=rows.filter(r=>r.match).length;
  const topics=topicNames(template);
  const note=topics.length?t(`Only clients who chose ${topics.join(', ')} are selected. A client who picked another service stays out.`,`Solo se marcan los clientes que eligieron ${topics.join(', ')}. Quien eligió otro servicio queda fuera.`):t('This tip is not tied to one service. Choose who should receive it.','Este consejo no está ligado a un servicio. Elige a quién enviarlo.');
  if(!rows.length)return `<p class="audience-note">${t('No clients yet. Send a quote first so SAFE knows which service each client chose.','Aún no hay clientes. Envía una cotización para que SAFE sepa qué servicio eligió cada uno.')}</p>`;
  const item=r=>{
    const why=r.match?r.hit.map(s=>s.service).join(', '):r.services.length?`${t('Other service','Otro servicio')}: ${r.services.map(s=>s.service).join(', ')}`:t('No service selected yet','Aún no tiene un servicio elegido');
    return `<label class="audience-row"><input type="checkbox" name="tipClient" value="${esc(r.email||r.name)}" ${r.match?'checked':''}><span><strong>${esc(r.name)}</strong><small>${esc(why)}</small></span></label>`;
  };
  return `<p class="audience-note">${note}</p><div class="audience-list">${rows.map(item).join('')}</div><small class="audience-note">${matches} ${t('clients match this service','clientes coinciden con este servicio')}</small>`;
}
function personalizeTip(body,person){
  const first=(person.name||'').trim().split(/\s+/)[0]||t('Client','Cliente');
  const address=person.address||t('Property address','Dirección');
  return String(body||'').replaceAll('{{first_name}}',first).replaceAll('{{property_address}}',address).replaceAll(t('Client','Cliente'),first);
}
function chosenTipClients(template){
  const rows=clientsForTip(template);
  return [...document.querySelectorAll('input[name="tipClient"]:checked')].map(input=>rows.find(p=>(p.email||p.name)===input.value)).filter(Boolean);
}
async function saveTipSend(status){
  const templateId=el('campaignTemplate')?.value||localStorage.getItem('safe-active-template')||'october';
  const template=monthlyTemplates.find(x=>x.id===templateId)||monthlyTemplates[0];
  const box=el('campaignPreview');
  const body=(box?.innerText||'').trim();
  if(!body){toast(t('Write the message before sending.','Escribe el mensaje antes de enviarlo.'));return}
  const picked=chosenTipClients(template);
  if(!picked.length){toast(t('Select the clients who need this service.','Selecciona los clientes que necesitan este servicio.'));return}
  if(box){box.contentEditable='false';box.classList.remove('editing')}
  saveMessageDraft(templateId,body);
  const channel=el('campaignChannel')?.value||'Gmail';
  const sendDate=el('campaignDate')?.value||'';
  const payload={realtorEmail:state.account?.email||'',templateId,title:t(template.title,template.titleEs),body,channel,sendDate,status,recipients:picked.map(p=>({name:p.name,email:p.email||'',phone:p.phone||'',address:p.address||'',body:personalizeTip(body,p),services:(p.hit?.length?p.hit:p.services)||[]}))};
  if(status==='Scheduled'&&sendDate&&sendDate<todayLocal()){toast(t('Choose today or a future date.','Elige hoy o una fecha futura.'));return}
  const button=el(status==='Scheduled'?'scheduleCampaign':'sendCampaign');if(button)button.disabled=true;
  let emailed=0,noEmail=[],mailOff=false;
  try{
    if(status==='Sent'&&channel==='Gmail'){
      for(const p of picked){
        if(!validEmail(p.email)){noEmail.push(p.name);continue}
        const result=await sendCompanyEmail(p.email,t(template.title,template.titleEs),personalizeTip(body,p));
        if(result==='sent')emailed++;
        else if(result==='off'){mailOff=true;break}
      }
    }
    let saved=null;
    try{const response=await fetch('/api/realtor/tips',{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify(payload)});if(response.ok)saved=await response.json()}catch{}
    if(!saved&&!emailed)throw new Error('save');
    if(saved)state.tipSends=[saved,...(state.tipSends||[])];
    render();
    const names=picked.map(p=>p.name).join(', ');
    const missing=noEmail.length?t(` No email for: ${noEmail.join(', ')}.`,` Sin correo: ${noEmail.join(', ')}.`):'';
    if(status==='Scheduled')toast(t(`Message scheduled for ${names} on ${sendDate}.`,`Mensaje programado para ${names} el ${sendDate}.`));
    else if(mailOff)toast(t('Message saved. The SAFE company email is not configured yet, so no email went out.','Mensaje guardado. El correo de SAFE aún no está configurado, así que no salió ningún correo.'));
    else if(channel==='Gmail')toast(t(`Email sent to ${emailed} of ${picked.length} clients from the SAFE company email.`,`Correo enviado a ${emailed} de ${picked.length} clientes desde el correo de SAFE.`)+missing);
    else toast(t(`Message saved for ${names}. ${channel} sends through the connected channel.`,`Mensaje guardado para ${names}. ${channel} se envía por el canal conectado.`));
  }finally{if(button)button.disabled=false}
}
async function loadTipStore(){
  absorbChosenServices();
  loadClientProfiles();
  const realtor=encodeURIComponent(state.account?.email||'');
  try{
    const [servicesRes,tipsRes,channelRes,profileRes,connRes]=await Promise.all([fetch(`/api/realtor/client-services?realtor=${realtor}`),fetch(`/api/realtor/tips?realtor=${realtor}`),fetch(`/api/realtor/channel-messages?realtor=${realtor}`),fetch(`/api/realtor/profile?realtor=${realtor}`),fetch(`/api/realtor/connections?realtor=${realtor}`)]);
    if(profileRes.ok){const p=await profileRes.json();state.logo=p.logo||'';paintRealtor()}
    if(connRes.ok){const rows=await connRes.json();if(Array.isArray(rows))state.connections=rows}
    if(servicesRes.ok){
      const remote=await servicesRes.json();
      if(Array.isArray(remote)){
        const local=loadClientServices();
        remote.forEach(row=>{
          const prev=local.find(x=>serviceKey(x)===serviceKey(row));
          if(prev)Object.assign(prev,row);else local.push(row);
        });
        saveClientServices(local);
      }
    }
    if(tipsRes.ok){const tips=await tipsRes.json();if(Array.isArray(tips))state.tipSends=tips}
    if(channelRes.ok){const rows=await channelRes.json();if(Array.isArray(rows))state.channelMessages=rows}
    const giftRes=await fetch(`/api/realtor/gift-cards?realtor=${realtor}`);
    if(giftRes.ok){const rows=await giftRes.json();if(Array.isArray(rows))state.giftCards=rows}
    const [settingsRes,plansRes]=await Promise.all([fetch('/api/realtor/repair-plan-settings'),fetch(`/api/realtor/repair-plans?realtor=${realtor}`)]);
    if(settingsRes.ok)Object.assign(state.planSettings,await settingsRes.json());
    if(plansRes.ok){const rows=await plansRes.json();if(Array.isArray(rows))state.plans=rows}
  }catch{}
}
