function messageDrafts(){try{return JSON.parse(localStorage.getItem(messageDraftKey())||'{}')}catch{return{}}}
function saveMessageDraft(id,text){const drafts=messageDrafts();drafts[id]=text;localStorage.setItem(messageDraftKey(),JSON.stringify(drafts))}
