function scheduleView(){
  const names=state.lang==='en'?['Sun','Mon','Tue','Wed','Thu','Fri','Sat']:['Dom','Lun','Mar','Mié','Jue','Vie','Sáb'];
  const now=new Date();
  const year=now.getFullYear(),month=now.getMonth();
  const start=new Date(year,month,1).getDay();
  const days=new Date(year,month+1,0).getDate();
  const visits=loadVisits().filter(v=>!v.done);
  const monthLabel=now.toLocaleDateString(state.lang==='en'?'en-US':'es-ES',{month:'long',year:'numeric'});
  const cells=Array.from({length:start},()=>`<div class="day muted"></div>`).join('')+Array.from({length:days},(_,i)=>{
    const day=i+1;
    const iso=`${year}-${String(month+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;
    const hits=visits.filter(v=>v.date===iso);
    return `<div class="day ${day===now.getDate()?'today':''}"><b>${day}</b>${hits.map(v=>`<button type="button" class="event-pill" data-edit-visit="${esc(v.id)}">${esc(v.time?v.time+' ':'')}${esc(v.client)}</button>`).join('')}</div>`;
  }).join('');
  const upcoming=visits.slice().sort((a,b)=>`${a.date}${a.time}`.localeCompare(`${b.date}${b.time}`)).map(v=>`<div class="schedule-item"><time>${esc(visitWhen(v))}</time><div><strong>${esc(v.client)}</strong><p>${esc(v.address||v.note||'')}</p><button type="button" class="text-button" data-edit-visit="${esc(v.id)}">${t('Edit visit','Editar visita')}</button></div></div>`).join('')||`<p>${t('No visits scheduled yet. Add one from Next Follow-ups.','Aún no hay visitas. Agrégalas en Próximos seguimientos.')}</p>`;
  return `${pageHead('CLIENT CALENDAR','Messages, follow-ups and property activity','Mensajes, seguimientos y propiedades','The visits you schedule appear on this calendar. Edit one to change the day or time.','Las visitas que programas aparecen en este calendario. Edita una para cambiar el día o la hora.',`<button class="button secondary" data-route="followups">${t('Schedule visit','Programar visita')}</button>`)}
  <div class="schedule-grid"><section class="card"><div class="card-head"><div><span class="eyebrow">${t('CALENDAR','CALENDARIO')}</span><h2>${esc(monthLabel)}</h2></div></div><div class="calendar">${names.map(n=>`<div class="day-name">${n}</div>`).join('')}${cells}</div></section><aside class="card"><span class="eyebrow">${t('UP NEXT','PRÓXIMOS')}</span><h2>${t('Scheduled visits','Visitas programadas')}</h2><div class="schedule-list section-gap">${upcoming}</div></aside></div>`;
}
const channelSetup={
  gmail:{name:'Gmail',field:['Gmail address','Correo de Gmail'],placeholder:'you@gmail.com',type:'email'},
  whatsapp:{name:'WhatsApp Business',field:['WhatsApp Business number','Número de WhatsApp Business'],placeholder:'+1 704 555 0100',type:'tel'},
  sms:{name:'SMS',field:['Phone number that sends texts','Teléfono que envía los textos'],placeholder:'+1 704 555 0100',type:'tel'},
  facebook:{name:'Facebook Messenger',field:['Facebook page name or link','Nombre o enlace de tu página de Facebook'],placeholder:'facebook.com/tu-pagina',type:'text'},
  instagram:{name:'Instagram Direct',field:['Instagram account','Cuenta de Instagram'],placeholder:'@tu_cuenta',type:'text'}
};
function connectionFor(channel){return (state.connections||[]).find(c=>c.channel===channel)}
function validChannelAccount(channel,value){
  const v=String(value||'').trim();
  if(channel==='gmail')return validEmail(v);
  if(channel==='whatsapp'||channel==='sms')return v.replace(/\D/g,'').length>=10;
  if(channel==='instagram')return /^@?[A-Za-z0-9._]{2,30}$/.test(v);
  return v.length>=3;
}
function ensureConnectModal(){
  if(el('connectModal'))return;
  const modal=document.createElement('div');
  modal.className='modal';
  modal.id='connectModal';
  modal.setAttribute('role','dialog');
  modal.innerHTML=`<form class="modal-card" id="connectForm"><div class="modal-head"><div><span class="eyebrow" id="connectEyebrow"></span><h2 id="connectTitle"></h2></div><button type="button" class="close" data-close-connect aria-label="${t('Close','Cerrar')}" data-aria-en="Close" data-aria-es="Cerrar">×</button></div><div class="form-grid"><label class="full"><span id="connectLabel"></span><input id="connectAccount" required></label><label class="full connect-consent"><input type="checkbox" id="connectConsent" required><span id="connectConsentText"></span></label></div><div class="modal-actions"><button type="button" class="button secondary" data-close-connect id="connectCancel"></button><button class="button primary" type="submit" id="connectSubmit"></button></div></form>`;
  document.body.appendChild(modal);
  modal.querySelectorAll('[data-close-connect]').forEach(b=>b.onclick=()=>modal.classList.remove('open'));
  modal.addEventListener('click',e=>{if(e.target===modal)modal.classList.remove('open')});
  el('connectForm').onsubmit=async e=>{
    e.preventDefault();
    const channel=modal.dataset.channel;
    const account=el('connectAccount').value.trim();
    if(!validChannelAccount(channel,account)){toast(t('Check the account you wrote.','Revisa la cuenta que escribiste.'));el('connectAccount').focus();return}
    if(!el('connectConsent').checked){toast(t('Confirm the authorization first.','Primero confirma la autorización.'));return}
    if(modal.dataset.saving==='1')return;
    const submit=el('connectSubmit'),label=submit.textContent;
    modal.dataset.saving='1';
    modal.querySelectorAll('input,button').forEach(n=>n.disabled=true);
    submit.innerHTML=`<span class="btn-spin" aria-hidden="true"></span>${t('Connecting…','Conectando…')}`;
    const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);
    try{
      const response=await fetch('/api/realtor/connections',{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify({realtorEmail:state.account?.email||'',channel,account}),signal:controller.signal});
      if(!response.ok){const body=await response.json().catch(()=>({}));throw new Error((state.lang==='es'?body.errorEs:body.error)||'')}
      const saved=await response.json();
      state.connections=[...(state.connections||[]).filter(c=>c.channel!==channel),saved];
      modal.classList.remove('open');
      render();
      toast(t(`${channelSetup[channel].name} connected`,`${channelSetup[channel].name} conectado`));
    }catch(err){toast(err.name==='AbortError'?t('The server took too long. Try again in a moment.','El servidor tardó demasiado. Intenta de nuevo en un momento.'):(err.message||t('The connection could not be saved.','No se pudo guardar la conexión.')))}
    finally{clearTimeout(timer);modal.dataset.saving='';modal.querySelectorAll('input,button').forEach(n=>n.disabled=false);submit.textContent=label}
  };
}
function openConnectModal(channel){
  ensureConnectModal();
  const spec=channelSetup[channel];if(!spec)return;
  const modal=el('connectModal');
  modal.dataset.channel=channel;
  el('connectEyebrow').textContent=t('AUTHORIZE CHANNEL','AUTORIZAR CANAL');
  el('connectTitle').textContent=t(`Connect ${spec.name}`,`Conectar ${spec.name}`);
  el('connectLabel').textContent=t(spec.field[0],spec.field[1]);
  const input=el('connectAccount');input.type=spec.type;input.placeholder=spec.placeholder;input.value=connectionFor(channel)?.account||'';
  el('connectConsent').checked=false;
  el('connectConsentText').textContent=t('I authorize SAFE to use this account to send my client messages, and my clients agreed to be contacted on this channel.','Autorizo a SAFE a usar esta cuenta para enviar mis mensajes a clientes, y mis clientes aceptaron ser contactados por este canal.');
  el('connectCancel').textContent=t('Cancel','Cancelar');
  el('connectSubmit').textContent=t('Authorize and connect','Autorizar y conectar');
  modal.classList.add('open');
  setTimeout(()=>input.focus(),30);
}
