function shrinkLogo(file){
  return new Promise((resolve,reject)=>{
    const reader=new FileReader();
    reader.onerror=()=>reject(new Error('read'));
    reader.onload=()=>{
      const src=String(reader.result||'');
      if(file.type==='image/svg+xml'){resolve(src);return}
      const img=new Image();
      img.onerror=()=>reject(new Error('image'));
      img.onload=()=>{
        const max=320,scale=Math.min(1,max/Math.max(img.width,img.height));
        const canvas=document.createElement('canvas');
        canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));
        canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);
        resolve(canvas.toDataURL('image/png'));
      };
      img.src=src;
    };
    reader.readAsDataURL(file);
  });
}
async function saveLogo(logo){
  const response=await fetch('/api/realtor/profile/logo',{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify({realtorEmail:state.account?.email||'',logo})});
  if(!response.ok){const body=await response.json().catch(()=>({}));throw new Error((state.lang==='es'?body.errorEs:body.error)||'')}
  state.logo=logo;
  paintRealtor();
  render();
}
