function persistReports(){try{sessionStorage.setItem('safe-realtor-reports',JSON.stringify(state.reports||[]))}catch{}}
function loadReports(){try{state.reports=JSON.parse(sessionStorage.getItem('safe-realtor-reports')||'[]')}catch{state.reports=[]}state.reportReady=(state.reports||[]).length>0;state.reportName=(state.reports||[]).map(r=>r.name).join(' · ')}
function reportFinding(key){for(const report of state.reports||[]){const finding=(report.findings||[]).find(f=>f.key===key);if(finding)return finding}return null}
function includeFinding(finding){
  if(state.estimate.some(x=>x.id===finding.estimateId))return;
  const catalog=finding.catalogId?state.catalog.find(x=>x.id===finding.catalogId):null,fromReport=String(finding.key||'').split(':')[0];
  if(catalog)state.estimate.push({...catalog,qty:1,finding:finding.detail||'',fromReport});
  else state.estimate.push({id:finding.estimateId,service:finding.service,category:finding.category||'Inspection',low:null,high:null,unit:'',notes:'',review:'',materials:'',inspector:finding.detail,finding:finding.detail||'',qty:1,fromReport});
  persistEstimate();
}
function dropReport(id){
  const report=(state.reports||[]).find(r=>r.id===id);if(!report)return;
  const rest=state.reports.filter(r=>r.id!==id);
  const stillFound=new Map();rest.forEach(r=>(r.findings||[]).forEach(f=>stillFound.set(f.estimateId,r.id)));
  const ids=new Set((report.findings||[]).map(f=>f.estimateId));
  const fromIt=x=>x.fromReport===id||(!x.fromReport&&x.finding&&ids.has(x.id));
  const linked=state.estimate.filter(fromIt),drop=linked.filter(x=>!stillFound.has(x.id));
  if(linked.length&&!confirm(t(`Delete “${report.name}”? ${drop.length} repairs that came from this report will also leave the estimate.`,`¿Borrar “${report.name}”? También se quitarán del estimado ${drop.length} reparaciones que venían de este reporte.`)))return;
  state.estimate=state.estimate.filter(x=>!fromIt(x)||stillFound.has(x.id)).map(x=>fromIt(x)?{...x,fromReport:stillFound.get(x.id)}:x);
  state.reports=rest;state.reportReady=rest.length>0;state.reportName=rest.map(r=>r.name).join(' · ');
  persistReports();persistEstimate();render();
  toast(drop.length?t(`Report deleted with its ${drop.length} repairs`,`Reporte borrado junto con sus ${drop.length} reparaciones`):t('Report deleted','Reporte borrado'));
}
const findingStop=new Set(['the','and','for','with','that','this','from','have','been','are','was','were','not','but','into','your','home','item','items','area','repair','repairs','recommend','recommended','inspector','missing','damaged','damage','replace','replacement','install','installation','service','condition','noted','note','see','per','all','any','needs','need','qualified','contractor','correction','visible','evidence','present','appears','appear','should','would','could','their','there','than','then','when','where','which','while','also','only','such','other','over','under','about','after','before','more','most','some','each','both','same','very','just','onto','upon','within','without','during','through','between','report','inspection','inspected','comment','comments','page','section','observed','observation']);
function decodePdfLiteral(body){let s='';for(let i=0;i<body.length;i++){const c=body[i];if(c!=='\\'){s+=c;continue}const n=body[++i];if(n==='n')s+='\n';else if(n==='r')s+='\r';else if(n==='t')s+='\t';else if(n==='('||n===')'||n==='\\')s+=n;else if(n>='0'&&n<='7'){let oct=n;while(oct.length<3&&body[i+1]>='0'&&body[i+1]<='7')oct+=body[++i];s+=String.fromCharCode(parseInt(oct,8))}else if(n)s+=n}return s}
function pdfOperatorsToText(src){
  if(!/Tj|TJ|\sTd|\sT\*/.test(src))return '';
  let i=0,out='',len=src.length;
  while(i<len){
    const c=src[i];
    if(c==='('){let j=i+1,depth=1,buf='';while(j<len&&depth){if(src[j]==='\\'){buf+=src[j]+(src[j+1]||'');j+=2;continue}if(src[j]==='(')depth++;else if(src[j]===')'){depth--;if(!depth)break}if(depth)buf+=src[j];j++}out+=decodePdfLiteral(buf);i=j+1;continue}
    if(c==='<'&&src[i+1]!=='<'){const j=src.indexOf('>',i+1);if(j<0)break;const hex=src.slice(i+1,j).replace(/\s+/g,'');if(/^[0-9A-Fa-f]+$/.test(hex)&&hex.length>=4&&hex.length%2===0){let s='';for(let k=0;k<hex.length;k+=2){const code=parseInt(hex.slice(k,k+2),16);if(code>=32&&code<=126)s+=String.fromCharCode(code)}out+=s}i=j+1;continue}
    if(c==='\n'||c==='\r'){out+='\n';i++;continue}
    if(src.startsWith('Tj',i)||src.startsWith('TJ',i)){out+=' ';i+=2;continue}
    if(src.startsWith('Td',i)||src.startsWith('TD',i)||src.startsWith('T*',i)){out+='\n';i+=2;continue}
    i++;
  }
  const text=out.replace(/[^\S\n]+/g,' ').replace(/\n /g,'\n').trim();
  const letters=(text.match(/[A-Za-z]/g)||[]).length;
  return letters>40&&letters/Math.max(text.length,1)>0.25?text:'';
}
function findBytes(hay,needle,from=0){outer:for(let i=from;i<=hay.length-needle.length;i++){for(let j=0;j<needle.length;j++)if(hay[i+j]!==needle[j])continue outer;return i}return -1}
async function inflateBytes(raw){
  for(const format of ['deflate','deflate-raw']){
    try{const stream=new Blob([raw]).stream().pipeThrough(new DecompressionStream(format));return new Uint8Array(await new Response(stream).arrayBuffer())}catch{}
  }
  return null;
}
async function pdfPlainText(file){
  const bytes=new Uint8Array(await file.arrayBuffer());
  const streamMark=[115,116,114,101,97,109];
  const endMark=[101,110,100,115,116,114,101,97,109];
  const parts=[];
  let cursor=0;
  while(cursor<bytes.length){
    const at=findBytes(bytes,streamMark,cursor);
    if(at<0)break;
    let start=at+streamMark.length;
    if(bytes[start]===13)start++;
    if(bytes[start]===10)start++;
    const end=findBytes(bytes,endMark,start);
    if(end<0)break;
    const dict=new TextDecoder('latin1').decode(bytes.subarray(Math.max(0,at-500),at));
    let data=bytes.subarray(start,end);
    if(data.length&&data[data.length-1]===10)data=data.subarray(0,data.length-1);
    if(data.length&&data[data.length-1]===13)data=data.subarray(0,data.length-1);
    if(!(/DCTDecode|JPXDecode/.test(dict)&&!/FlateDecode/.test(dict))){
      let text='';
      if(/FlateDecode/.test(dict)){const inflated=await inflateBytes(data);if(inflated)text=pdfOperatorsToText(new TextDecoder('latin1').decode(inflated))}
      else text=pdfOperatorsToText(new TextDecoder('latin1').decode(data));
      if(text)parts.push(text);
    }
    cursor=end+endMark.length;
    if(parts.join('\n').length>350000)break;
  }
  return parts.join('\n').replace(/[ \t]+\n/g,'\n').replace(/\n{3,}/g,'\n\n').trim();
}
function simplifyInspection(text,reportId){
  const rows=String(text||'').split(/\n+/).map(s=>s.replace(/\s+/g,' ').trim()).filter(s=>s.length>18&&!/^(page \d+|table of contents|\d+)$/i.test(s));
  const sentences=[];
  let buf='';
  rows.forEach(row=>{buf=buf?`${buf} ${row}`:row;if(/[.!?:]$/.test(row)||buf.length>260){sentences.push(buf);buf=''}});
  if(buf)sentences.push(buf);
  const cue=/repair|damag|leak|missing|deteriorat|inoperable|not function|deficient|defect|recommend|corrosion|rott|crack|unsafe|hazard|moisture|mold|loose|broken|worn|failed|clog|gfci|double[ -]?tap|anti-tip|flue|flashing|downspout|sag|stain|improper|incorrect|inadequate|absent|terminat|unsealed|compressed/i;
  const fine=/satisfactor|serviceable|appeared to be|within normal|no visible defect|none noted|no issues|good condition|functioning properly|operating properly/i;
  const candidates=sentences.filter(s=>s.length>35&&s.length<420&&cue.test(s)&&!fine.test(s)).slice(0,80);
  const used=new Set();
  const findings=[];
  candidates.forEach(sentence=>{
    let best=null,bestScore=0;
    state.catalog.forEach(row=>{
      let score=0;
      [['inspector',3],['customer_en',2],['service',1]].forEach(([field,weight])=>{
        normalized(row[field]||'').split(/[;,/|]+/).map(s=>s.trim()).filter(s=>s.length>5).forEach(phrase=>{
          const words=phrase.split(/\s+/).filter(w=>w.length>2&&!findingStop.has(w));
          if(words.length<2)return;
          const hits=words.filter(w=>normalized(sentence).includes(w));
          if(hits.length===words.length)score+=(8+hits.length)*weight;
          else if(hits.length>=2)score+=hits.length*weight;
        });
      });
      if(score>bestScore){bestScore=score;best=row}
    });
    if(best&&bestScore>=8){
      if(used.has(best.id))return;
      used.add(best.id);
      findings.push({key:`${reportId}:${findings.length}`,estimateId:best.id,catalogId:best.id,service:best.service,detail:sentence.slice(0,240),category:best.category,low:best.low,high:best.high,unit:best.unit,level:/safety|hazard|shock|carbon monoxide|smoke|gfci|anti-tip|gas leak|structural/i.test(sentence)?'Safety':'Priority'});
    }else if(findings.filter(f=>!f.catalogId).length<12){
      const title=sentence.replace(/\s+/g,' ').slice(0,90);
      findings.push({key:`${reportId}:${findings.length}`,estimateId:`pdf:${reportId}:${findings.length}`,catalogId:'',service:title,detail:sentence.slice(0,240),category:t('Inspection finding','Hallazgo de inspección'),low:null,high:null,unit:'',level:/safety|hazard|shock|gfci|carbon monoxide/i.test(sentence)?'Safety':'Review'});
    }
  });
  const rank={Safety:0,Priority:1,Review:2,Routine:3};
  return findings.sort((a,b)=>(rank[a.level]??9)-(rank[b.level]??9)).slice(0,30);
}
async function analyzeReports(list){
  if(!state.loggedIn){state.pendingRoute='report';openModal('loginModal');return}
  const files=[...list||[]].filter(Boolean);
  if(!files.length)return;
  const accepted=[];
  files.forEach(file=>{
    if(file.type&&file.type!=='application/pdf'&&!/\.pdf$/i.test(file.name)){toast(t('Please choose a PDF report','Selecciona un reporte PDF'));return}
    if(file.size>25*1024*1024){toast(t('Each PDF must be 25 MB or less','Cada PDF debe pesar 25 MB o menos'));return}
    if((state.reports||[]).some(r=>r.name===file.name&&r.size===file.size)){toast(t(`${file.name} is already in the list`,`${file.name} ya está en la lista`));return}
    accepted.push(file);
  });
  if(!accepted.length)return;
  state.reportReading=true;
  const zone=el('uploadZone');
  if(zone)zone.innerHTML=`<div class="upload-icon">◌</div><h2>${t('Reading the inspection and simplifying findings…','Leyendo la inspección y simplificando hallazgos…')}</h2><p>${esc(accepted.map(f=>f.name).join(' · '))}</p><div class="progress" style="max-width:360px;margin:18px auto 0"><i id="analysisProgress" style="width:18%"></i></div>`;
  else toast(t('Reading the inspection…','Leyendo la inspección…'));
  let added=0;
  for(const file of accepted){
    if(el('analysisProgress'))el('analysisProgress').style.width='55%';
    const reportId='rep'+Date.now().toString(36)+Math.random().toString(36).slice(2,6);
    let text='';
    try{text=await pdfPlainText(file)}catch{text=''}
    const findings=simplifyInspection(text,reportId);
    state.reports.push({id:reportId,name:file.name,size:file.size,empty:text.length<80,findings});
    added++;
  }
  state.reportReading=false;
  state.reportReady=state.reports.length>0;
  state.reportName=state.reports.map(r=>r.name).join(' · ');
  persistReports();
  render();
  const last=state.reports[state.reports.length-1];
  const total=(last&&last.findings||[]).length;
  toast(total?t(`${added} report${added>1?'s':''} read. ${total} findings are ready to quote.`,`${added} reporte${added>1?'s':''} leído${added>1?'s':''}. ${total} hallazgos listos para cotizar.`):t('The report was kept. No selectable findings were found in the last file.','El reporte se conservó. En el último archivo no había hallazgos con texto seleccionable.'));
}
